INSERT INTO texts VALUES(1557499,'Silver Bow and Arrow','A Fairy-Type monster equipped with this card increases its ATK and DEF by 300 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1561110,'ABC-Dragon Buster',replace(replace('"A-Assault Core" + "B-Buster Drake" + "C-Crush Wyvern"	\r\nMust first be Special Summoned (from your Extra Deck) by banishing the above cards you control and/or from your GY. \r\n(You do not use "Polymerization".) \r\nOnce per turn (Quick Effect): You can discard 1 card, then target 1 card on the field; banish it. \r\nDuring your opponent''s turn (Quick Effect): You can Tribute this card, then target 3 of your banished LIGHT Machine Union monsters with different names; Special Summon them.','\r',char(13)),'\n',char(10)),'Discard 1 card; banish 1 card on the field','Tribute this card; Special Summon your banished Union monsters','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1566817,'Cupid Serve',replace(replace('Unaffected by the activated effects of monsters, except monsters whose Level is equal or lower than this card. \r\nYou can banish up to 3 cards from your GY; increase this card''s Level by that number, until the end of this turn. \r\nYou can only use this effect of "Cupid Serve" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
