INSERT INTO texts VALUES(1580833,'Dinomist Stegosaur',replace(replace('Pendulum Scale = 3\r\n[ Pendulum Effect ]\r\nIf another "Dinomist" card(s) you control would be destroyed by battle or an opponent''s card effect, you can destroy this card instead.\r\n----------------------------------------\r\n[ Monster Effect ]\r\nIf another Pendulum Monster you control battles an opponent''s monster, after damage calculation: You can destroy those monsters.','\r',char(13)),'\n',char(10)),'Use "Dinomist Stegosaur"''s effect instead of being destroyed?','','','','','','','','','','','','','','','');
