INSERT INTO texts VALUES(2191144,'Night Papilloperative',replace(replace('3 Level 4 monsters	\r\nOnce per turn: You can detach 1 Xyz Material from this card; this card gains 300 ATK for each Xyz Material attached to a monster on the field.','\r',char(13)),'\n',char(10)),'Increase ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2196767,'Gambler of Legend',replace(replace('Once per turn, you can toss a coin 3 times and apply the appropriate effect:\r\n● 3 Heads: Destroy all monsters your opponent controls.\r\n● 2 Heads: Discard 1 random card from your opponent''s hand.\r\n● 1 Head: Destroy 1 card you control.\r\n● 3 Tails: Discard your entire hand.','\r',char(13)),'\n',char(10)),'Toss a coin','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2203790,'XX-Saber Hyunlei',replace(replace('1 Tuner + 1+ non-Tuner "X-Saber" monsters	\r\nWhen this card is Synchro Summoned: You can target up to 3 Spells/Traps on the field; destroy them.','\r',char(13)),'\n',char(10)),'Destroy','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2204038,'Valkyrie Brunhilde',replace(replace('Unaffected by your opponent''s Spell effects. \r\nGains 500 ATK for each monster your opponent controls. \r\nWhen an opponent''s monster declares an attack: You can have this card lose exactly 1000 DEF, and if you do, your "Valkyrie" monsters cannot be destroyed by battle this turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2204140,'Book of Life','Target 1 Zombie monster in your GY and 1 monster in your opponent''s GY; Special Summon the first target, also banish the second target.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2220237,'Secure Gardna',replace(replace('1 Cyberse Link Monster	\r\nAfter this card is Special Summoned, you take no effect damage for the rest of this turn. \r\nOnce per turn, if you would take battle or effect damage, you take no damage. \r\nCannot be used as Link Material. \r\nYou can only control 1 "Secure Gardna".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2250266,'Morphtronic Staplen',replace(replace('● While in Attack Position: Your opponent cannot select another monster as an attack target.	\r\nIf this card is destroyed by battle, the monster that destroyed this card loses 300 ATK.\r\n● While in Defense Position: This card cannot be destroyed by battle.	\r\nIf this card is attacked, after damage calculation, select 1 face-up Attack Position monster your opponent controls. \r\nChange it to Defense Position and this card to Attack Position.','\r',char(13)),'\n',char(10)),'Decrease ATK','Change to Attack Position','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2254222,'Speedroid Wing Synchron',replace(replace('Pendulum Scale = 4\r\n[ Pendulum Effect ]\r\nOnce per turn: You can destroy this card and 1 Level 2 WIND Pendulum Monster Card in your Pendulum Zone, and if you do, Special Summon 1 "Clear Wing Synchro Dragon" from your Extra Deck (this is treated as a Synchro Summon), also for the rest of this turn, cards in your Pendulum Zones cannot be destroyed by card effects, and you cannot Special Summon, except WIND monsters.\r\n----------------------------------------\r\n[ Monster Effect ]\r\nIf this card is added to your Extra Deck face-up, and you control 2 or more different Types of WIND Synchro Monsters: You can send 1 "Speedroid" Spell/Trap from your Deck to the GY. \r\nYou can only use this effect of "Speedroid Wing Synchron" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','Send to the GY','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2263869,'Ultimate Slayer',replace(replace('Your opponent cannot activate monster effects in response to this card''s activation. \r\nSend 1 monster from your Extra Deck to the GY, then target 1 monster your opponent controls with the same card type (Fusion, Synchro, Xyz, Pendulum, or Link); shuffle it into the Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2263870,'Ultimate Slayer',replace(replace('Your opponent cannot activate monster effects in response to this card''s activation. \r\nSend 1 monster from your Extra Deck to the GY, then target 1 monster your opponent controls with the same card type (Fusion, Synchro, Xyz, Pendulum, or Link); shuffle it into the Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2266498,'Vendread Reunion',replace(replace('Reveal 1 "Vendread" Ritual Monster in your hand, Special Summon any number of your banished "Vendread" monsters with different names, in face-down Defense Position, whose total Levels exactly equal the Level of the revealed Ritual Monster, Tribute all those face-down Defense Position monsters, then Ritual Summon that Ritual Monster from your hand. \r\nYou must be able to Ritual Summon to activate and to resolve this effect.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2273734,'Satellarknight Altair',replace(replace('If this card is Summoned: You can target 1 "tellarknight" monster in your GY, except "Satellarknight Altair"; Special Summon that monster in Defense Position, also monsters you control cannot attack for the rest of this turn, except "tellarknight" monsters. \r\nYou can only use this effect of "Satellarknight Altair" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2287848,'Vendread Revolution',replace(replace('Discard 1 card, then target 1 "Vendread" monster and 1 Ritual Spell in your GY; Special Summon that monster in Defense Position, and if you do, add that Ritual Spell to your hand. \r\nYou can banish this card from your GY, then target 5 of your banished Zombie monsters; shuffle them into your Deck, then draw 1 card. \r\nYou can only use each effect of "Vendread Revolution" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295440,'One for One','Send 1 monster from your hand to the GY; Special Summon 1 Level 1 monster from your hand or Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295441,'One for One','Send 1 monster from your hand to the GY; Special Summon 1 Level 1 monster from your hand or Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295831,'Symbol of Friendship',replace(replace('To activate this card, you must draw it for your normal draw in your Draw Phase while your opponent controls 3 or more monsters and you control no cards, reveal it, and keep it revealed until the Main Phase 1. \r\nDuring your Main Phase 1 that same turn: You can activate this card from your hand; reveal 1 card from your Deck, and add it to your hand.','\r',char(13)),'\n',char(10)),'Keep "Symbol of Friendship" revealed?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2311090,'Spright Carrot',replace(replace('If you control a Level/Link 2 monster, you can Special Summon this card (from your hand). \r\nYou can only Special Summon "Spright Carrot" once per turn this way. \r\nWhen your opponent activates a Spell/Trap Card or effect (Quick Effect): You can Tribute 1 other Level/Rank/Link 2 monster; negate that effect, then if you Tributed a Rank/Link 2 monster to activate this effect, you can destroy that card. \r\nYou can only use this effect of "Spright Carrot" once per turn.','\r',char(13)),'\n',char(10)),'','','Destroy that card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2311603,'Overdrive','An all-terrain armored vehicle armed with a heavy-duty machine gun.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2314238,'Dark Magic Attack','If you control "Dark Magician": Destroy all Spells and Traps your opponent controls.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2316186,'Princess Curran',replace(replace('This card cannot be Normal Summoned or Set. \r\nThis card cannot be Special Summoned except with "Trial of the Princesses". \r\nDuring your Standby Phase, inflict 600 damage to your opponent for each monster they control.','\r',char(13)),'\n',char(10)),'Inflict LP damage','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2322421,'Road Warrior',replace(replace('"Road Synchron" + 2+ non-Tuner monsters	\r\nOnce per turn: You can Special Summon 1 Level 2 or lower Warrior or Machine monster from your Deck.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2326738,'Des Lacooda',replace(replace('Once per turn: You can change this card to face-down Defense Position. \r\nIf this card is Flip Summoned: Draw 1 card.','\r',char(13)),'\n',char(10)),'Change to face-down Defense Position','Draw 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2333365,'Tyr of the Nordic Champions',replace(replace('Your opponent''s monsters cannot target "Nordic" monsters for attacks, except "Tyr of the Nordic Champions". \r\nIf there is no other "Nordic" monster on the field, destroy this card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2333466,'Gandora-G the Dragon of Destruction',replace(replace('Gains 300 ATK for each banished card. \r\nYou can only use each of the following effects of "Gandora-G the Dragon of Destruction" once per turn. \r\nIf you control "Shining Sarcophagus": You can Special Summon this card from your hand. \r\nYou can pay half your LP; destroy as many other cards on the field as possible, and if you do, banish them, then Special Summon 1 Level 7 or lower monster that mentions "Shining Sarcophagus" from your Deck, and increase its Level by the number of cards destroyed by this effect.','\r',char(13)),'\n',char(10)),'Special Summon from the hand','Destroy a card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2339825,'T.G. Close',replace(replace('When a Spell/Trap Card, or monster effect, is activated while you control a Machine "T.G." monster: Negate the activation, and if you do, destroy that card. \r\nIf a Synchro Monster(s) is banished while this card is in your GY: You can Set this card, but banish it when it leaves the field. \r\nYou can only use 1 "T.G. Close" effect per turn, and only once that turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2344618,'Lunalight Masquerade',replace(replace('During your Main Phase, if this card was activated this turn: You can send 1 "Lunalight" monster from your Deck to the GY. \r\nIf you Fusion Summon a "Lunalight" monster: You can add 1 "Polymerization" from your GY or banishment to your hand, then you can discard 1 card, and if you do, once, if you Fusion Summon a "Lunalight" monster this turn, you can also banish monsters from your GY as material. \r\nYou can only use each effect of "Lunalight Masquerade" once per turn.','\r',char(13)),'\n',char(10)),'Send to the GY','Add to hand','Discard a card?','The effect of "Lunalight Masquerade" is currently being applied.','','','','','','','','','','','','');
INSERT INTO texts VALUES(2347477,'Micro Coder',replace(replace('If a Cyberse monster you control would be used as Link Material for a "Code Talker" monster, this card in your hand can also be used as material. \r\nIf this card is sent from the hand or field to the GY as material for the Link Summon of a "Code Talker" monster: You can either add 1 "Cynet" Spell/Trap from your Deck to your hand, or, if this card on the field was used as material, you can add 1 Level 4 Cyberse monster instead. \r\nYou can only use each effect of "Micro Coder" once per turn.','\r',char(13)),'\n',char(10)),'','Send from the field to the GY','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2347656,'Lovely Labrynth of the Silver Castle',replace(replace('Your opponent cannot activate monster effects in response to the activation of your Normal Trap Cards. \r\nYou can only use each of the following effects of "Lovely Labrynth of the Silver Castle" once per turn. \r\nYou can target 1 Normal Trap in your GY; Set it to your field, but it cannot be activated unless you control a Fiend monster. \r\nIf another monster(s) leaves the field by your Normal Trap effect (except during the Damage Step): You can destroy 1 card in your opponent''s hand (at random) or their field.','\r',char(13)),'\n',char(10)),'','Select 1 card in your opponent''s hand or on their field to destroy','The effect of "Lovely Labrynth of the Silver Castle" is currently being applied.','Randomly select a card in your opponent''s hand to destroy','Select 1 card your opponent controls to destroy','','','','','','','','','','','');
INSERT INTO texts VALUES(2347657,'Lovely Labrynth of the Silver Castle',replace(replace('Your opponent cannot activate monster effects in response to the activation of your Normal Trap Cards. \r\nYou can only use each of the following effects of "Lovely Labrynth of the Silver Castle" once per turn. \r\nYou can target 1 Normal Trap in your GY; Set it to your field, but it cannot be activated unless you control a Fiend monster. \r\nIf another monster(s) leaves the field by your Normal Trap effect (except during the Damage Step): You can destroy 1 card in your opponent''s hand (at random) or their field.','\r',char(13)),'\n',char(10)),'','Select 1 card in your opponent''s hand or on their field to destroy','The effect of "Lovely Labrynth of the Silver Castle" is currently being applied.','Randomly select a card in your opponent''s hand to destroy','Select 1 card your opponent controls to destroy','','','','','','','','','','','');
INSERT INTO texts VALUES(2347658,'Lovely Labrynth of the Silver Castle',replace(replace('Your opponent cannot activate monster effects in response to the activation of your Normal Trap Cards. \r\nYou can only use each of the following effects of "Lovely Labrynth of the Silver Castle" once per turn. \r\nYou can target 1 Normal Trap in your GY; Set it to your field, but it cannot be activated unless you control a Fiend monster. \r\nIf another monster(s) leaves the field by your Normal Trap effect (except during the Damage Step): You can destroy 1 card in your opponent''s hand (at random) or their field.','\r',char(13)),'\n',char(10)),'','Select 1 card in your opponent''s hand or on their field to destroy','The effect of "Lovely Labrynth of the Silver Castle" is currently being applied.','Randomly select a card in your opponent''s hand to destroy','Select 1 card your opponent controls to destroy','','','','','','','','','','','');
INSERT INTO texts VALUES(2356994,'Great Long Nose',replace(replace('This card cannot be Special Summoned. \r\nThis card returns to the owner''s hand during the End Phase of the turn that this card is Normal Summoned or flipped face-up. \r\nIf this card inflicts Battle Damage to your opponent''s Life Points, your opponent skips their next Battle Phase.','\r',char(13)),'\n',char(10)),'Return to hand','Skip the Battle Phase','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2359348,'Pendulum Area','If all monsters you control are Pendulum Monsters (min. 1): Target 2 cards in your Pendulum Zones; destroy both cards, and if you do, neither player can Special Summon for the rest of this turn, except by Pendulum Summon.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2362787,'Light of Redemption','Pay 800 Life Points, then target 1 of your banished LIGHT monsters; add that target to your hand.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2364438,'Mayakashi Return',replace(replace('Take 1 "Mayakashi" card from your Deck, except "Mayakashi Return", and either add it to your hand or send it to the GY. \r\nYou can only activate 1 "Mayakashi Return" per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2368215,'Abyss Actor - Hyper Director',replace(replace('1 "Abyss Actor" Pendulum Monster	\r\nYou can target 1 card in your Pendulum Zone; Special Summon it, then place 1 "Abyss Actor" Pendulum Monster with a different name, from your Deck or face-up Extra Deck, to your Pendulum Zone, also you cannot Normal or Special Summon monsters for the rest of this turn, except "Abyss Actor" monsters. \r\nYou can only use this effect of "Abyss Actor - Hyper Director" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2370081,'Steel Shell','A WATER monster equipped with this card increases its ATK by 400 points and decreases its DEF by 200 points.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2371506,'Xyz Reflect','When a Spell Card, Trap Card, or monster effect is activated that targets a face-up Xyz Monster(s) on the field: Negate the activation, and if you do, destroy it, then inflict 800 damage to your opponent.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2372506,'Chaos Magical Hats',replace(replace('When your opponent activates a monster effect, or a Normal Spell/Trap Card: Choose 3 Spells/Traps with different names from your Deck and 1 monster in your Main Monster Zone that mentions "Light and Darkness Ritual". \r\nSpecial Summon the Spells/Traps as Normal Monsters (Spellcaster/DARK/Level 8/ATK 0/DEF 0) in face-down Defense Position (their names become "Chaos Magical Hats" even while face-down), Set the chosen monster if it is face-up, and shuffle them on the field. \r\nThen your opponent''s activated effect becomes "Destroy 1 monster your opponent controls in face-down Defense Position".','\r',char(13)),'\n',char(10)),'Activate','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2376209,'Paleozoic Eldonia',replace(replace('Target 1 face-up monster on the field; it gains 500 ATK/DEF until the end of this turn. \r\nOnce per Chain, when a Trap Card is activated while this card is in your GY: You can Special Summon this card as a Normal Monster (Aqua/WATER/Level 2/ATK 1200/DEF 0).	\r\n(This card is NOT treated as a Trap.) \r\nIf Summoned this way, this card is unaffected by monster effects, also banish it when it leaves the field.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2377034,'Neo Flamvell Hedgehog',replace(replace('If this card is destroyed by battle: Target 1 card in your opponent''s GY; banish it. \r\nIf this card on the field is destroyed by card effect: Target 1 FIRE monster with 200 or less DEF in your GY, except "Neo Flamvell Hedgehog"; add that target to your hand.','\r',char(13)),'\n',char(10)),'Banish','Add to hand','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2390019,'Ojamassimilation',replace(replace('Reveal 1 LIGHT Machine Fusion Monster from your Extra Deck and banish any number of "Ojama" monsters from your hand, face-up field, and/or GY; Special Summon Fusion Materials with different names whose names are specifically listed on the card you revealed, from your hand, Deck, and/or GY, equal to the number of monsters banished to activate this effect. \r\nYou can banish this card from your GY, then target 3 of your banished "Ojama" monsters; shuffle them into the Deck, then draw 1 card.','\r',char(13)),'\n',char(10)),'Continue selecting monsters to banish?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2396042,'Steel Cavalry of Dinon',replace(replace('Pendulum Scale = 5\r\n----------------------------------------\r\n[ Monster Effect ]\r\nAt the start of the Damage Step, if this card battles a Pendulum Monster: This card''s ATK and DEF become half its current ATK and DEF until the end of the Damage Step.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2403771,'Power Tool Dragon',replace(replace('1 Tuner + 1+ non-Tuner monsters	\r\nOnce per turn: You can reveal 3 Equip Spells from your Deck, then your opponent randomly adds 1 of them to your hand, and shuffle the other cards into the Deck. \r\nIf this card would be destroyed while equipped with an Equip Spell(s), you can send 1 of those cards to the GY instead.','\r',char(13)),'\n',char(10)),'Select an Equip Card to add to your hand','Use "Power Tool Dragon"''s effect instead of being destroyed?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2405631,'Guoglim, Spear of the Ghoti',replace(replace('1 Fish Tuner + 1+ non-Tuner monsters	\r\nAt the start of the Damage Step, if this card battles an opponent''s monster: You can banish that opponent''s monster. \r\nDuring your opponent''s Standby Phase: You can banish this card, then, if the monsters used as material for this card''s Synchro Summon are all in your GY, you can Special Summon all of them, but banish them when they leave the field. \r\nYou can only use each effect of "Guoglim, Spear of the Ghoti" once per turn.','\r',char(13)),'\n',char(10)),'','','Special Summon the Synchro Material monster?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2407147,'Laval Volcano Handmaiden','When this card is sent to the GY, if you have a "Laval" monster in your GY other than "Laval Volcano Handmaiden": You can send 1 "Laval" monster from your Deck to your GY.','Send to the GY','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2407234,'Number 69: Heraldry Crest',replace(replace('3 Level 4 monsters	\r\nIf this card is Special Summoned: Negate the effects of all other Xyz Monsters currently on the field. \r\nYou can target 1 other face-up Xyz Monster on the field; until the End Phase, this card''s name becomes that monster''s original name, also replace this effect with that monster''s original effects. \r\nYou can only use this effect of "Number 69: Heraldry Crest" once per turn.','\r',char(13)),'\n',char(10)),'Negate the effect','Gain effect','End the copied effect','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2411269,'Agave Dragon',replace(replace('2+ monsters, except Tokens	\r\nIf this card is Link Summoned: You can apply these effects in sequence, depending on the Types of monsters in the GYs (skip over any that do not apply). \r\nYou can only use this effect of "Agave Dragon" once per turn.\r\n● Inflict 100 damage to your opponent for each Dragon.\r\n● This card gains 200 ATK for each Dinosaur.\r\n● All monsters your opponent currently controls lose 300 ATK for each Sea Serpent.\r\n● You gain 400 LP for each Wyrm.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2414168,'Interrupt Resistor',replace(replace('When you take battle damage: You can Special Summon this card from your hand, and if you do, it gains ATK equal to the damage you took. \r\nOnce per turn, during damage calculation, when another Defense Position monster you control is attacked by an opponent''s monster (Quick Effect): You can activate this effect; during this damage calculation, your attacked monster''s DEF becomes equal to this card''s DEF, also it cannot be destroyed by that battle.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2420921,'Shire, Lightsworn Spirit',replace(replace('Gains 300 ATK for each "Lightsworn" monster with a different name in your GY. \r\nOnce per turn, during your End Phase: Send the top 2 cards of your Deck to the GY.','\r',char(13)),'\n',char(10)),'Send 2 cards from your Deck to the GY','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2434862,'Cubic Ascension',replace(replace('When an opponent''s monster declares an attack: Special Summon 1 "Vijam the Cubic Seed" from your Deck, and if you do, change the attack target to it, and perform damage calculation. \r\nIf your opponent''s LP are at least 2000 higher than yours: You can banish this card from your GY; Special Summon 1 "Vijam the Cubic Seed" from your hand, Deck, or GY, then, if only your opponent controlled a monster when this effect was activated, you can Special Summon up to 2 more "Vijam the Cubic Seed". \r\nYou can only use this effect of "Cubic Ascension" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon and change the attack target','Special Summon','Special Summon another monster?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2460565,'Marauding Captain',replace(replace('Monsters your opponent controls cannot target Warrior monsters for attacks, except this one. \r\nWhen this card is Normal Summoned: You can Special Summon 1 Level 4 or lower monster from your hand.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2461031,'Inzektor Ladybug',replace(replace('Once per turn: You can equip 1 "Inzektor" monster from your hand or GY to this card. \r\nWhile this card is equipped to a monster, that monster''s Level is increased by 2, also it gains ATK/DEF equal to this card''s ATK/DEF. \r\nWhile this card is equipped to a monster: You can send this Equip Card to the GY, then target 1 face-up monster you control; increase that target''s Level by 1 or 2.','\r',char(13)),'\n',char(10)),'Equip','Increase Level','Increase by 1 Level','Increase by 2 Levels','','','','','','','','','','','','');
INSERT INTO texts VALUES(2463794,'Fiendsmith''s Requiem',replace(replace('1 LIGHT Fiend monster	\r\nYou can only Special Summon "Fiendsmith''s Requiem(s)" once per turn. \r\nDuring the Main Phase (Quick Effect): You can Tribute this card; Special Summon 1 "Fiendsmith" monster from your hand or Deck. \r\nYou can target 1 LIGHT non-Link Fiend monster you control; equip this card from your field or GY to that monster you control as an Equip Spell that gives it 600 ATK. \r\nYou can only use this effect of "Fiendsmith''s Requiem" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','Equip effect','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2468169,'Sealmaster Meisei','One of the few people who has a good command of Talismans. His history is a mystery.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2483611,'Water Omotics','Transforms the water overflowing from a jar into attacking dragons.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2501624,'Dark Magician Girl the Magician''s Apprentice',replace(replace('You can Special Summon this card (from your hand) by discarding 1 card, and if you do, this card''s name becomes "Dark Magician Girl". \r\nYou can only Special Summon "Dark Magician Girl the Magician''s Apprentice" once per turn this way. \r\nIf this card is Normal or Special Summoned: You can add 1 "Shining Sarcophagus" from your Deck to your hand. \r\nYou can only use this effect of "Dark Magician Girl the Magician''s Apprentice" once per turn. \r\nGains 300 ATK for each monster that mentions "Shining Sarcophagus" in the GYs.','\r',char(13)),'\n',char(10)),'Special Summon','Add to hand','Increase ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2504891,'Skull Knight','"Tainted Wisdom" + "Ancient Brain"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2507443,'Prima Light',replace(replace('Activate 1 of these effects;\r\n● Tribute 1 EARTH Warrior monster, and if you do, Special Summon 1 LIGHT Warrior monster from your hand or Deck.\r\n● During the Main Phase: Immediately after this effect resolves, Normal Summon 1 Warrior monster from your hand.	\r\nDuring your Main Phase: You can banish this card from your GY; add 1 Warrior or Fairy "Cyber" monster from your Deck to your hand. \r\nYou can only use 1 "Prima Light" effect per turn, and only once that turn.','\r',char(13)),'\n',char(10)),'Activate','Add to hand','Tribute and Special Summon','Normal Summon','','','','','','','','','','','','');
INSERT INTO texts VALUES(2511717,'Legendary Six Samurai - Kageki',replace(replace('When this card is Normal Summoned: You can Special Summon 1 Level 4 or lower "Six Samurai" monster from your hand. \r\nWhile you control a "Six Samurai" monster with a different name, this card gains 1500 ATK.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2519690,'Sky Galloping Gaia the Dragon Champion',replace(replace('1 "Gaia The Fierce Knight" monster + 1 Dragon-Type monster	\r\nThis card''s name becomes "Gaia the Dragon Champion" while it is on the field. \r\nIf this card is Special Summoned: You can add 1 "Spiral Spear Strike" from your Deck or Graveyard to your hand. \r\nWhen this card declares an attack on an opponent''s monster: You can change the battle position of that opponent''s monster.','\r',char(13)),'\n',char(10)),'Add 1 "Spiral Spear Strike" card to your hand','Change an opponent''s monster battle position','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2521011,'Brotherhood of the Fire Fist - Swallow',replace(replace('You can Special Summon this card (from your hand) by sending 3 face-up "Fire Formation" Spell/Trap Cards you control to the Graveyard. \r\nWhen this card is Normal or Special Summoned: You can Set 1 "Fire Formation" Trap Card directly from your Deck. \r\nYou can only use this effect of "Brotherhood of the Fire Fist - Swallow" once per turn. \r\nFace-up Beast-Warrior-Type monsters you control cannot be targeted by your opponent''s card effects.','\r',char(13)),'\n',char(10)),'Set','Draw','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2525268,'Defender, the Magical Knight',replace(replace('If this card is Normal Summoned: Place 1 Spell Counter on it (max. 1). \r\nOnce per turn, if a Spellcaster monster(s) on the field would be destroyed, you can remove 1 Spell Counter from your field for each of those monsters instead.','\r',char(13)),'\n',char(10)),'Place Spell Counters','Use "Defender, the Magical Knight"''s effect instead of being destroyed?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2526224,'Fire King High Avatar Kirin',replace(replace('During the Main Phase, if this card is in your hand (Quick Effect): You can destroy 1 other FIRE monster in your hand or face-up field, and if you do, Special Summon this card. \r\nIf this card is destroyed and sent to the GY: You can Special Summon 1 "Fire King" monster from your hand or GY, except "Fire King High Avatar Kirin", then you can destroy 1 card on the field. \r\nYou can only use each effect of "Fire King High Avatar Kirin" once per turn.','\r',char(13)),'\n',char(10)),'','','Destroy 1 card on the field?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2530830,'Galaxy-Eyes Cipher Blade Dragon',replace(replace('3 Level 9 monsters	\r\nYou can also Xyz Summon this card by using a Rank 8 "Galaxy-Eyes" Xyz Monster you control as material. \r\n(Transfer its materials to this card.) \r\nCannot be used as material for an Xyz Summon. \r\nOnce per turn: You can detach 1 material from this card, then target 1 card on the field; destroy it. \r\nIf this Xyz Summoned card you control, is destroyed by battle with an opponent''s attacking monster, or destroyed by an opponent''s card effect, and sent to your GY: You can target 1 "Galaxy-Eyes Cipher Dragon" in your GY; Special Summon it.','\r',char(13)),'\n',char(10)),'Xyz Summon by using the "Galaxy-Eyes" Xyz Monster as material?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2542230,'Red Cocoon',replace(replace('Target 1 Dragon Synchro Monster you control; equip this card to it. \r\nWhile it is battling an opponent''s monster, until the end of the Damage Step, negate the effects of all face-up monsters your opponent controls. \r\nDuring the End Phase, if this card is in the GY because it was sent there this turn: You can target 1 "Red Dragon Archfiend" in your GY; Special Summon it.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2547033,'Altergeist Haunted Rock',replace(replace('If this card was Set by the effect of an "Altergeist" card, you can activate it the turn it was Set. \r\nWhen this card is activated: Send 1 "Altergeist" monster from your hand to the GY. \r\nWhen your opponent activates a Trap Card: You can send 1 "Altergeist" monster from your hand to the GY; negate that effect, and if you do, destroy that card. \r\nYou can only use each effect of "Altergeist Haunted Rock" once per turn.','\r',char(13)),'\n',char(10)),'','Activate by applying the effect of "Altergeist".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2561846,'Corruption Cell "A"','Place 1 A-Counter on 1 face-up monster on your opponent''s side of the field.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2563463,'Wandering Gryphon Rider',replace(replace('During the Main Phase, if you control no monsters, or control an "Adventurer Token" (Quick Effect): You can Special Summon this card from your hand. \r\nWhen a card or effect is activated while you control an "Adventurer Token" (Quick Effect): You can shuffle this card into the Deck, and if you do, negate that activation, and if you do that, destroy that card. \r\nYou can only use each effect of "Wandering Gryphon Rider" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2572890,'Majespecter Tempest','When a monster(s) would be Special Summoned, or a monster effect is activated: Tribute 1 WIND Spellcaster monster; negate the Summon or activation, and if you do, destroy that card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2584136,'Shocktopus',replace(replace('When this card is destroyed by battle with an opponent''s monster and sent to the Graveyard: You can equip this card to that opponent''s monster. \r\nThat monster''s ATK becomes 0, also it cannot change its battle position.','\r',char(13)),'\n',char(10)),'Equip','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2602411,'Wizard Buster Destruction Sword',replace(replace('You can target 1 "Buster Blader" you control; equip this monster from your hand or your side of the field to that target. \r\nWhile this card is equipped to a monster, monsters in your opponent''s Graveyard cannot activate their effects. \r\nYou can send this Equip Card to the Graveyard, then target 1 "Destruction Sword" monster in your Graveyard, except "Wizard Buster Destruction Sword"; add it to your hand.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2606417,'Reversal Box',replace(replace('Once per turn, during the Standby Phase: Roll a six-sided die and place counters on this card up to the result (max. 6). \r\nWhen a monster effect is activated on your opponent''s field, or once per battle, during damage calculation, if an opponent''s monster attacks: You can remove 1 counter from this card, then target 1 of those monsters; toss a coin and call it. \r\nIf you call it right, you can Special Summon 1 monster that mentions "Dark Time Wizard" from your Deck, and if you do, until the end of this turn, change the targeted monster''s ATK to 0, also its effects are negated.','\r',char(13)),'\n',char(10)),'Place a counter','Toss a coin','Select the number of counters to place','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2609443,'Chronomaly Vimana',replace(replace('2 Level 5 monsters	\r\nOnce per turn (Quick Effect): You can target 1 face-up monster on the field and 1 Xyz Monster or "Chronomaly" monster in your GY; that monster on the field gains half the ATK of that monster in the GY (until the end of this turn), then attach that monster from the GY to this card as material. \r\nOnce per turn, when your opponent activates a monster effect (Quick Effect): You can detach 2 materials from this card; negate the activation.','\r',char(13)),'\n',char(10)),'Increase ATK and replenish materials','Negate an opponent''s monster activation','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2618045,'Photon Chargeman',replace(replace('Once per turn: You can make this card''s ATK become double its original ATK, until your next Standby Phase. \r\nThis card cannot attack the turn you activate this effect.','\r',char(13)),'\n',char(10)),'Change ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2618725,'GMX Partner Selandea',replace(replace('You can reveal this card in your hand; Special Summon 1 "GMX" monster or 1 Dinosaur monster from your hand, also you can only attack directly with "GMX" monsters for the rest of this turn. \r\nIf this card is Special Summoned by a monster effect: You can Special Summon 1 Level 4 or lower "GMX" or Dinosaur monster from your hand, GY, or banishment in Defense Position. \r\nYou can only use each effect of "GMX Partner Selandea" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon from the hand','Special Summon from the hand, GY, or banishment','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2619149,'Gladiator Beast Samnite',replace(replace('When this card, that was Special Summoned by the effect of a "Gladiator Beast" monster, destroys an opponent''s monster by battle and sends it to the GY: You can add 1 "Gladiator Beast" card from your Deck to your hand. \r\nAt the end of the Battle Phase, if this card battled: You can shuffle it into the Deck; Special Summon 1 "Gladiator Beast" monster from your Deck, except "Gladiator Beast Samnite".','\r',char(13)),'\n',char(10)),'Search the Deck','Special Summon','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2625939,'Spool Code',replace(replace('When an opponent''s monster declares a direct attack, while you have 3 or more Cyberse monsters in your GY: Negate the attack, then, you can Special Summon up to 3 "Spool Tokens" (Cyberse/LIGHT/Level 1/ATK 0/DEF 0) in Defense Position. \r\nThese Tokens cannot be Tributed for a Tribute Summon.','\r',char(13)),'\n',char(10)),'Special Summon a Token?','Select the number of Tokens to Special Summon','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2625940,'Spool Token','Special Summoned with the effect of "Spool Code." This Token cannot be used as a Tribute for a Tribute Summon.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2645637,'Yuki-Onna, the Absolute Zero Mayakashi',replace(replace('2+ Zombie monsters	\r\nYou can only control 1 "Yuki-Onna, the Absolute Zero Mayakashi". \r\nNegate any activated effects of your opponent''s banished monsters. \r\nIf a monster is Special Summoned from the GY, or a monster effect is activated in the GY (except during the Damage Step): You can target 1 other face-up monster on the field; change its ATK to 0, and if you do, negate its effects. \r\nYou can use this effect of "Yuki-Onna, the Absolute Zero Mayakashi" up to twice per turn.','\r',char(13)),'\n',char(10)),'ATK becomes 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2648201,'ZW - Sleipnir Mail',replace(replace('You can target 1 "Utopia" monster you control; equip this monster from your hand or your side of the field to that target. \r\nIt gains 1000 ATK. \r\nWhen this card you control is sent to your Graveyard because the equipped monster was destroyed by your opponent''s card (by battle or card effect): You can target 1 "Utopia" monster in your Graveyard; Special Summon that target. \r\nYou can only control 1 "ZW - Sleipnir Mail".','\r',char(13)),'\n',char(10)),'Equip','Special Summon','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2656842,'Beetrooper Scout Buggy',replace(replace('You cannot Special Summon monsters, except Insect monsters. \r\nIf this card is Normal or Special Summoned: You can Special Summon 1 "Beetrooper Scout Buggy" from your hand, Deck, or GY. \r\nYou can only use this effect of "Beetrooper Scout Buggy" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2665273,'Jormungandr, Generaider Boss of Eternity',replace(replace('2+ Level 9 monsters	\r\nYou can only control 1 "Jormungandr, Generaider Boss of Eternity". \r\nThis card''s original ATK/DEF become 1000 x its number of materials. \r\n(Quick Effect): You can detach 1 material from this card; each player draws 1 card, then each player that drew attaches 1 card from their hand or field to this card. \r\nYou can only use this effect of "Jormungandr, Generaider Boss of Eternity" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2671330,'Hyper Hammerhead','At the end of the Damage Step, if an opponent''s monster that battled this card is not destroyed: Return that opponent''s monster to the hand.','Return to hand','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2674965,'Argostars - Home Stadium',replace(replace('Once per turn: You can pay 1000 LP; add 1 "Argostars" card from your GY or banishment to your hand. \r\nEach time a Continuous Trap in the Spell & Trap Zone is Special Summoned to your field, inflict 500 damage to your opponent. \r\nOnce per Chain, if a Continuous Trap activates its effect in your Monster Zone, while you have a banished "Argostars" monster: You can target 1 face-up card your opponent controls; negate its effects until the end of this turn.','\r',char(13)),'\n',char(10)),'Add to hand','Negate','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2694423,'Medusa Worm',replace(replace('Once per turn: You can flip this card to face-down Defense Position. \r\nIf this card is Flip Summoned: Target 1 monster your opponent controls; destroy that target.','\r',char(13)),'\n',char(10)),'Change to face-down Defense Position','Destroy','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2725599,'Rescue-ACE Arbitrator',replace(replace('2+ FIRE monsters	\r\nYou can only Special Summon "Rescue-ACE Arbitrator(s)" once per turn. \r\nIf this card is Link Summoned: You can add 1 "Rescue-ACE Hydrant" or "Rescue-ACE HQ" from your Deck or GY to your hand. \r\nIf you activate a "Rescue-ACE" Quick-Play Spell Card or a "Rescue-ACE" Normal Trap Card (except during the Damage Step): You can target 1 card your opponent controls; destroy it. \r\nYou can only use this effect of "Rescue-ACE Arbitrator" twice per turn.','\r',char(13)),'\n',char(10)),'Add to hand','Destroy','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2729285,'Fluffal Cat',replace(replace('If this card is sent to the Graveyard as a Fusion Material for a Fusion Summon: You can target 1 "Polymerization" in your Graveyard; add it to your hand. \r\nYou can only use this effect of "Fluffal Cat" once per turn.','\r',char(13)),'\n',char(10)),'Search the Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2729965,'Spatial Trunade',replace(replace('Return up to 2 cards on the field to the hand, then each player places cards from their hand on the bottom of the Deck in any order equal to the number returned to their hand. \r\nYou can only activate 1 "Spatial Trunade" per turn.','\r',char(13)),'\n',char(10)),'Activate','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2732323,'Decoy Dragon','If this card is targeted for an attack: Target 1 Level 7 or higher Dragon monster in your GY; Special Summon it, and if you do, change the attack target to it and perform damage calculation.','Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2743001,'Crystron Phoenix',replace(replace('1 Tuner Synchro Monster + 1+ non-Tuner Synchro Monsters	\r\nIf this card is Synchro Summoned: You can banish all Spells and Traps your opponent controls and in their GY. \r\nIf this Synchro Summoned card is destroyed by battle or card effect: You can target 1 other monster in your GY; Special Summon it.','\r',char(13)),'\n',char(10)),'Banish Spells/Traps on the field and in the GY','Special Summon from the GY','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2752099,'Rose Shaman',replace(replace('You can Tribute this card; draw 1 card. \r\nYou can banish this card from your GY, then target 1 Plant monster in your GY; add it to your hand, then, if you added a Plant monster whose original Level is 7 or higher, you can send 1 Plant monster from your Deck to the GY. \r\nYou can only use 1 "Rose Shaman" effect per turn, and only once that turn.','\r',char(13)),'\n',char(10)),'','','Send 1 Plant monster from your Deck to the GY again?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2759860,'Graydle Impact',replace(replace('You can target 1 other "Graydle" card you control and 1 card your opponent controls; destroy them. \r\nDuring your End Phase: You can add 1 "Graydle" card from your Deck to your hand. \r\nYou can only use 1 "Graydle Impact" effect per turn, and only once that turn.','\r',char(13)),'\n',char(10)),'Destroy a card','Add 1 "Graydle" card from your Deck to your hand','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2766877,'Daigusto Phoenix',replace(replace('2 Level 2 monsters	\r\nOnce per turn: You can detach 1 Xyz Material from this card to target 1 face-up WIND monster you control; this turn, it can attack twice during each Battle Phase.','\r',char(13)),'\n',char(10)),'Attack twice','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772236,'Wattchimera',replace(replace('1 "Watt" Tuner + 1+ non-Tuner Thunder monsters	\r\nThis card can attack directly. \r\nIf this card inflicts battle damage to your opponent by a direct attack: Place 1 random card from your opponent''s hand on top of their Deck.','\r',char(13)),'\n',char(10)),'Return to the Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772337,'Promethean Princess, Bestower of Flames',replace(replace('2+ Effect Monsters	\r\nYou cannot Special Summon, except FIRE monsters. \r\nYou can only use each of the following effects of "Promethean Princess, Bestower of Flames" once per turn. \r\nDuring your Main Phase: You can Special Summon 1 FIRE monster from your GY. \r\nIf a monster(s) is Special Summoned to your opponent''s field, while this card is in your GY (except during the Damage Step): You can target 1 FIRE monster you control and 1 monster your opponent controls; destroy them, and if you do, Special Summon this card.','\r',char(13)),'\n',char(10)),'Revive','Destroy a monster','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772338,'Promethean Princess, Bestower of Flames',replace(replace('2+ Effect Monsters	\r\nYou cannot Special Summon, except FIRE monsters. \r\nYou can only use each of the following effects of "Promethean Princess, Bestower of Flames" once per turn. \r\nDuring your Main Phase: You can Special Summon 1 FIRE monster from your GY. \r\nIf a monster(s) is Special Summoned to your opponent''s field, while this card is in your GY (except during the Damage Step): You can target 1 FIRE monster you control and 1 monster your opponent controls; destroy them, and if you do, Special Summon this card.','\r',char(13)),'\n',char(10)),'Revive','Destroy a monster','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2779999,'Wall of Thorns','When a Plant-Type monster you control is targeted for an attack: Destroy all Attack Position monsters your opponent controls.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2783661,'Majesty with Eyes of Blue',replace(replace('Send 1 "Blue-Eyes" monster from your hand or Deck to the GY, then target 1 face-up monster on the field; it cannot attack while it is face-up on the field. \r\nYou can only activate 1 "Majesty with Eyes of Blue" per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2792265,'Servant of Catabolism','This monster may attack your opponent''s Life Points directly.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2801664,'Ancient Warriors - Valiant Zhang De',replace(replace('Gains 300 ATK for each monster your opponent controls, during your turn only. \r\nYou can only use each of the following effects of "Ancient Warriors - Valiant Zhang De" once per turn.\r\n● If you control 2 or more "Ancient Warriors" monsters: You can Special Summon this card from your hand.\r\n● If your opponent controls more monsters than you do: You can activate this effect; this card can make up to 2 attacks on monsters during each Battle Phase this turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2810642,'PSY-Framegear Beta',replace(replace('Cannot be Normal Summoned/Set. \r\nMust be Special Summoned by a card effect, and cannot be Special Summoned by other ways. \r\nWhen an opponent''s monster declares an attack while you control no monsters: You can Special Summon both this card from your hand and 1 "PSY-Frame Driver" from your hand, Deck, or Graveyard, and if you do, destroy the attacking monster, then end the Battle Phase. \r\nDuring the End Phase, banish the face-up monsters Special Summoned by this effect.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2815176,'Zebufera, Vaalmonican Hallow Heathen',replace(replace('1 Effect Monster	\r\nCannot be Link Summoned unless you have 3 or more Resonance Counters on Fiend Monster Card(s) in your Pendulum Zone. \r\nYou can only Special Summon "Zebufera, Vaalmonican Hallow Heathen" once per turn. \r\nIf a card(s) you control would be destroyed by battle or card effect, you can remove 3 Resonance Counters from your Pendulum Zone instead. \r\nOnce per opponent''s turn (Quick Effect): You can target 1 of your "Vaalmonica" Normal Spells/Traps that is banished or in your GY; apply that card''s activation effect.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2819435,'Pacifis, the Phantasm City',replace(replace('(This card''s name is always treated as "Umi".)	\r\nYou cannot Normal or Special Summon Effect Monsters the turn you activate either of this card''s effects (even if this card leaves the field). \r\nOnce per turn, if you Normal or Special Summon exactly 1 Normal Monster (and no other cards): Add 1 "Phantasm Spiral" card from your Deck to your hand. \r\nIf your opponent activates a card or effect (except during the Damage Step), and you control no Tokens: You can Special Summon 1 "Phantasm Spiral Token" (Wyrm-Type/WATER/Level 8/ATK 2000/DEF 2000).','\r',char(13)),'\n',char(10)),'Search the Deck','Token','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2819436,'Phantasm Spiral Token','Special Summoned with the effect of "Pacifis, the Phantasm City."','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2830619,'Flame Viper','A fire-breathing snake whose speed makes it a difficult target.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2830693,'Rainbow Kuriboh',replace(replace('You can only use each effect of "Rainbow Kuriboh" once per turn.\r\n● When an opponent''s monster declares an attack: You can target that attacking monster; equip this card from your hand to that monster.	\r\nIt cannot attack.\r\n● When an opponent''s monster declares a direct attack while this card is in your GY: You can Special Summon this card, but banish it when it leaves the field.','\r',char(13)),'\n',char(10)),'Equip','Special Summon','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2833249,'D. Tribe','All monsters on your side of the field are treated as Dragon-Types until the End Phase of this turn.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2834264,'Beetrooper Armor Horn',replace(replace('2 Insect monsters	\r\nYou cannot Special Summon monsters, except Insect monsters. \r\nYou can only use each of the following effects of "Beetrooper Armor Horn" once per turn. \r\nDuring your Main Phase, you can: Immediately after this effect resolves, Normal Summon 1 Insect monster. \r\nIf this card is in your GY: You can banish 3 other Insect monsters from your GY; Special Summon this card, but banish it when it leaves the field.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2843014,'Nimble Sunfish',replace(replace('When this card is destroyed by battle and sent to the Graveyard, send 1 Fish-Type monster from your Deck to the Graveyard. \r\nThen, you can Special Summon 1 "Nimble Sunfish" from your Deck.','\r',char(13)),'\n',char(10)),'Send to the GY','Special Summon "Nimble Sunfish"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2851070,'Reflect Bounder',replace(replace('Before damage calculation, if this card is being attacked by an opponent''s monster, and was in Attack Position at the start of the Damage Step: Inflict damage to your opponent equal to the attacking monster''s ATK. \r\nIf you do, after damage calculation: Destroy this card.','\r',char(13)),'\n',char(10)),'Inflict damage','Self-destruct','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2857636,'Knightmare Phoenix',replace(replace('2 monsters with different names	\r\nIf this card is Link Summoned: You can discard 1 card, then target 1 Spell/Trap your opponent controls; destroy it, then, if this card was co-linked when this effect was activated, you can draw 1 card. \r\nYou can only use this effect of "Knightmare Phoenix" once per turn. \r\nCo-linked monsters you control cannot be destroyed by battle.','\r',char(13)),'\n',char(10)),'','Draw a card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2863439,'Fiend Reflection #2','A bird-beast that summons reinforcements with a hand mirror.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2881864,'Naglfar, Generaider Boss of Fire',replace(replace('You can only control 1 "Naglfar, Generaider Boss of Fire". \r\nIf a card(s) you control would be destroyed by battle or card effect, you can destroy 1 "Generaider" monster or 1 Beast-Warrior monster you control instead. \r\nYou can only use this effect of "Naglfar, Generaider Boss of Fire" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2896663,'ZW - Dragonic Halberd',replace(replace('2 Level 5 monsters	\r\nCannot attack directly. \r\nOnce per turn: You can detach 1 material from this card; add 1 "Zexal" Spell/Trap from your Deck to your hand. \r\nYou can target 1 "Utopia" monster you control; equip this card you control to it. \r\nIt gains 3000 ATK. \r\nWhen the equipped monster destroys a monster by battle: You can Special Summon to your field any number of "ZW -" Monster Cards equipped to it.','\r',char(13)),'\n',char(10)),'Search the Deck','Treat as an Equip Card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2903036,'Tribute Doll',replace(replace('Tribute 1 monster; Special Summon 1 Level 7 monster from your hand that can be Normal Summoned/Set. \r\nIt cannot attack this turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2906250,'Grappler','A devious snake with a thick body that wraps around an enemy monster and squeezes the life out of it.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2906939,'Ashtrashen - Gateway to the Worlds Beyond',replace(replace('You can target any number of face-down cards you control; add "Ashtra" cards from your Deck to your hand with different names from each other, except Field Spells, equal to the number of those targeted cards that are still face-down, then send those face-down cards to the GY. \r\nIf a card(s) becomes Set on the field, while you control an "Ashtra" monster and a face-down card (except during the Damage Step): You can target 1 card on the field; return it to the hand. \r\nYou can only use each effect of "Ashtrashen - Gateway to the Worlds Beyond" once per turn.','\r',char(13)),'\n',char(10)),'Add to hand','Return to the hand','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2924048,'Karakuri Cash Shed',replace(replace('Activate only if you control a "Karakuri" monster in face-up Defense Position. \r\nNegate the activation of an opponent''s Spell/Trap Card and destroy it.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2926176,'Curse of Royal','When a Spell/Trap Card is activated that targets 1 Spell/Trap on the field (and no other cards) and would destroy it: Negate the activation, and if you do, destroy that card.','Destroy','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2930675,'World Legacy Key',replace(replace('When this card is activated: You can target 1 of your banished "Mekk-Knight" monsters or "World Legacy" cards; add it to your hand. \r\nNegate any opponent''s Trap effect that activates in the same column as a "Mekk-Knight" monster you control.','\r',char(13)),'\n',char(10)),'Add the banished card to your hand?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2932235,'Thousand Umbral Horror',replace(replace('(Quick Effect): You can send this card from your hand or field to the GY; place 1 "Seventh Barian''s" from your hand or Deck face-up in your Field Zone, also you cannot Special Summon from the Extra Deck until the end of your next turn, except Xyz Monsters. \r\nIf an Xyz Monster(s) is Special Summoned while this card is in your GY (except during the Damage Step): You can Special Summon this card, also you take no effect damage from your card effects for the rest of this turn. \r\nYou can only use each effect of "Thousand Umbral Horror" once per turn.','\r',char(13)),'\n',char(10)),'Place in the Field Zone','Special Summon','The effect of "Thousand Umbral Horror" is currently being applied.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2948263,'Gogogo Golem - Golden Form',replace(replace('Cannot be Normal Summoned/Set. \r\nMust be Special Summoned (from your hand) by Tributing 1 "Gogogo" monster. \r\nThis card''s ATK becomes double the original ATK of the Tributed monster. \r\nAny battle damage your opponent takes from attacks involving this card is halved. \r\nOnce per turn, when a monster effect is activated on your opponent''s field (Quick Effect): This card loses exactly 1500 ATK, and if it does, negate that effect.','\r',char(13)),'\n',char(10)),'Negate the effect','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2956282,'Naturia Barkion',replace(replace('1 EARTH Tuner + 1+ non-Tuner EARTH monsters	\r\nWhen a Trap Card is activated (Quick Effect): You can banish 2 cards from your GY; negate the activation, and if you do, destroy that card. \r\nThis card must be face-up on the field to activate and to resolve this effect.','\r',char(13)),'\n',char(10)),'Negate the activation of a Trap Card and destroy it','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2957055,'Wicked Dragon with the Ersatz Head','A two-headed dragon with a pair of jaws that can tear an enemy to shreds.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2964201,'Ryu-Ran','A vicious little dragon sheltered in an egg that looks deceptively harmless.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2971090,'Orion the Battle King','None have lived to tell tales of this powerful battle fairy.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2971446,'Sales Pitch',replace(replace('If your opponent adds a card(s) from the Deck to their hand, except by drawing them, by their card effect: Reveal 1 card from your Deck, and add it to your hand, but you cannot activate cards, or the effects of cards, with that name for the rest of this turn. \r\nYou can only activate 1 "Sales Pitch" per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2978414,'Number 46: Dragluon',replace(replace('2 Level 8 Dragon-Type monsters	\r\nOnce per turn, if you control no other monsters: You can detach 1 Xyz Material from this card, then activate 1 of these effects.\r\n● Special Summon 1 Dragon-Type monster from your hand.\r\n● Target 1 Dragon-Type monster your opponent controls; take control of that target.\r\n● Dragon-Type monsters your opponent controls cannot activate their effects until the end of your opponent''s turn.','\r',char(13)),'\n',char(10)),'Special Summon 1 Dragon monster from your hand','Gain control of 1 Dragon monster your opponent controls','Dragon monsters your opponent controls cannot activate their effects','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2980764,'Consecrated Light',replace(replace('Neither player can Normal or Special Summon DARK monsters or declare an attack with a DARK monster. \r\nThis card cannot be destroyed by battle with a DARK monster, also you take no battle damage from that battle.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2986553,'Twilight Rose Knight',replace(replace('Monsters your opponent controls cannot target Plant monsters for attacks. \r\nWhen this card is Normal Summoned: You can Special Summon 1 Level 4 or lower Plant monster from your hand.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2992036,'Meklord Astro the Eradicator',replace(replace('Target 3 "Meklord" monsters with different names in your GY; add them to your hand, OR Special Summon them, ignoring their Summoning conditions. \r\nUntil the end of your next turn after this card is activated, you cannot Special Summon monsters, except Machine monsters. \r\nIf you control a "Meklord Astro" monster: You can banish this card from your GY; destroy 1 Synchro Monster your opponent controls, and if you do, inflict damage to your opponent equal to its original ATK. \r\nYou can only use each effect of "Meklord Astro the Eradicator" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2992467,'Click & Echo',replace(replace('Cannot be used as material for a Fusion, Synchro, or Xyz Summon. \r\nCannot be Tributed while face-up in the Monster Zone. \r\nIf this card is sent to the GY as material for a Link Summon: Special Summon this card in Defense Position, to the opponent''s field of the player that Link Summoned. \r\nYou can only use this effect of "Click & Echo" twice per turn. \r\nWhile this card, that was Summoned by its effect, is in the Monster Zone, you must keep your hand revealed.','\r',char(13)),'\n',char(10)),'','Keep your hand revealed','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2994495,'Fuhma Wave','Target 1 face-up monster on the field; destroy 1 monster on the field with the same Attribute, but a different name, as that monster.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3019642,'Cyberdark Keel',replace(replace('If this card is Normal Summoned: Target 1 Level 3 or lower Dragon monster in your GY; equip that Dragon monster to this card. \r\nGains ATK equal to the original ATK of the monster equipped to it by this effect. \r\nIf this card destroys an opponent''s monster by battle: Inflict 300 damage to your opponent. \r\nIf this card would be destroyed by battle, destroy that equipped monster, instead.','\r',char(13)),'\n',char(10)),'Equip','Inflict damage','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3026686,'Valkyrie Dritte',replace(replace('If this card is Normal or Special Summoned: You can add 1 "Valkyrie" card from your Deck to your hand, except "Valkyrie Dritte". \r\nYou can only use this effect of "Valkyrie Dritte" once per turn. \r\nGains 200 ATK for each of your opponent''s banished monsters.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3027001,'Fake Trap',replace(replace('You can only activate this card when your opponent uses an effect of a Spell, Trap, or Effect Monster to destroy Trap Card(s) on your side of the field. \r\nDestroy this card as a substitute of those Trap Card(s) and the other Trap Card(s) are not destroyed. \r\nIf a Set card(s) would have been destroyed, pick up and see the Set card(s).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3030892,'Test Ape','When this card is destroyed by battle and sent to the Graveyard, you can Special Summon 1 Level 4 or lower "Gladiator Beast" monster from your Deck.','Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3040496,'Chaos Ruler, the Chaotic Magical Dragon',replace(replace('1 Tuner + 1+ non-Tuner monsters	\r\nIf this card is Synchro Summoned: You can excavate the top 5 cards of your Deck, and if you do, you can add 1 excavated LIGHT or DARK monster to your hand, also send the remaining cards to the GY. \r\nYou can banish 1 LIGHT and 1 DARK monster from your hand and/or GY, except this card; Special Summon this card from your GY, but banish it when it leaves the field. \r\nYou can only use each effect of "Chaos Ruler, the Chaotic Magical Dragon" once per turn.','\r',char(13)),'\n',char(10)),'','Select a card to add to your hand?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3048768,'Angello Vaalmonica',replace(replace('Pendulum Scale = 3\r\n[ Pendulum Effect ]\r\nEach time you gain LP while you control a Fiend Monster Card in your other Pendulum Zone, place 1 Resonance Counter on this card. \r\nOnce per turn, when an opponent''s monster declares an attack, you can: Immediately after this effect resolves, Link Summon 1 "Vaalmonica" Link Monster.\r\n----------------------------------------\r\n[ Monster Effect ]\r\nIf this card is in your hand: You can discard 1 other card; take 1 "Dimonno Vaalmonica" from your Deck, and place this card and that card in your Pendulum Zones. \r\nDuring your Main Phase, if this card was Normal or Special Summoned this turn: You can banish 1 "Vaalmonica" Normal Spell/Trap from your GY; apply whichever effect on that card includes gaining LP. \r\nYou can only use each effect of "Angello Vaalmonica" once per turn.','\r',char(13)),'\n',char(10)),'','Place this card and "Dimonno Vaalmonica" from your Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3055018,'Obsidim, the Ashened City',replace(replace('Face-up Special Summoned monsters your opponent controls become Pyro during your turn only. \r\nYou can only use each of the following effects of "Obsidim, the Ashened City" once per turn. \r\nDuring your End Phase: You can target 1 "Obsidim, the Ashened City" in your GY; place it on the bottom of your Deck, then draw 1 card. \r\nIf this card in the Field Zone is destroyed or banished: You can Special Summon 1 "Ashened" monster from your Deck.','\r',char(13)),'\n',char(10)),'','Recycle and draw','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3055837,'Trap of Board Eraser',replace(replace('When an effect that inflicts damage to your Life Points is activated (except Battle Damage), negate the damage to your Life Points. \r\nYour opponent then selects 1 card from his/her hand and discards it to his/her Graveyard.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3056267,'Invader of the Throne',replace(replace('FLIP: Target 1 monster your opponent controls; switch control of it with this card. \r\nThis effect cannot be activated during the Battle Phase.','\r',char(13)),'\n',char(10)),'Switch control','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3064425,'Superheavy Samurai Soulbang Cannon',replace(replace('You can target 1 "Superheavy Samurai" monster you control; equip this monster from your hand or field to that target. \r\nIt gains 1000 DEF. \r\nDuring the Battle Phase, when your opponent activates a card or effect while you control a Defense Position "Superheavy Samurai" monster (Quick Effect): You can banish this card from your GY; negate the activation, and if you do, destroy it, then destroy as many monsters on the field as possible (min. 1), and if you do, both players take 1000 damage.','\r',char(13)),'\n',char(10)),'Equip to a "Superheavy Samurai" monster','Negate and destroy','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3064783,'Shining Umbral Horror',replace(replace('If you Normal or Special Summon an "Umbral Horror" monster(s) and/or a "Masquerade" Xyz Monster(s) (except during the Damage Step): You can Special Summon this card from your hand, and if you do, draw 1 card, then if you drew an "Umbral Horror" monster, you can Special Summon it. \r\nCan be treated as 2 materials for the Xyz Summon of a "Number" Xyz Monster that requires 3 or more materials. \r\nYou can only use each effect of "Shining Umbral Horror" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','Special Summon?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3070049,'Snow Dragon','When this card is destroyed by battle or by a card effect and sent to the Graveyard: Place 1 Ice Counter on each face-up monster on the field.','Place a counter','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3072077,'Return Zombie',replace(replace('During your Standby Phase: You can pay 500 Life Points; add this card from your Graveyard to your hand. \r\nYou must have no cards in your hand to activate and to resolve this effect.','\r',char(13)),'\n',char(10)),'Add to hand','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3072808,'Blackwing - Hillen the Tengu-wind',replace(replace('If you take 2000 or more battle damage from your opponent''s monster''s direct attack while this card is in your GY: Target 1 Level 3 or lower "Blackwing" monster in your GY; Special Summon both that monster and this card from the GY, but negate their effects. \r\nYou can only use this effect of "Blackwing - Hillen the Tengu-wind" once per Duel.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3078380,'Timaeus the United Dragon',replace(replace('You can send 1 Spellcaster monster, or 1 Spell/Trap that mentions "Dark Magician", from your hand or face-up field to the GY; Special Summon this card from your hand. \r\nDuring your Main Phase: You can Fusion Summon 1 Fusion Monster from your Extra Deck, using monsters from your hand or field as material, including a Spellcaster monster. \r\nYou can only use each effect of "Timaeus the United Dragon" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3078576,'Yata-Garasu',replace(replace('Cannot be Special Summoned. \r\nDuring the End Phase of the turn this card was Normal Summoned or flipped face-up: Return it to the hand. \r\nIf this card inflicts battle damage to your opponent: Skip the Draw Phase of their next turn.','\r',char(13)),'\n',char(10)),'Return to the hand','Skip your next Draw Phase','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3084730,'Bio-Insect Armor',replace(replace('If this card is in your hand or GY and you do not control "Bio-Insect Armor": You can target 1 Insect monster you control; equip this card to it, but banish it when it leaves the field, also banish this Equip Card when it leaves the field. \r\nYou can only use this effect of "Bio-Insect Armor" once per turn. \r\nThe equipped monster gains 1500 ATK/2000 DEF during the Battle Phase and Main Phase 2, only.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3096468,'Tatsunecro',replace(replace('If this Normal Summoned/Set monster would be used as Synchro Material, 1 monster in your hand can be used as 1 of the other materials. \r\nIf you do this, all materials for that Summon are banished instead of being sent to the GY. \r\nYou cannot Special Summon monsters, except Zombie monsters.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3103067,'Attack Guidance Armor',replace(replace('When a monster declares an attack: Activate 1 of these effects;\r\n● Destroy the attacking monster.\r\n● Target 1 monster on either field, except the attacking monster; change the attack target to it and perform damage calculation.	\r\nYou can only activate 1 "Attack Guidance Armor" per turn.','\r',char(13)),'\n',char(10)),'Destroy the attacking monster','Change attack target','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3105404,'Brilliant Spark',replace(replace('If a face-up "Gem-Knight" monster(s) you control is destroyed by your opponent''s attack or card effect: Target 1 of those destroyed monsters; inflict damage to your opponent equal to its original ATK. \r\nIf this card is in your Graveyard: You can send 1 "Gem-Knight" card from your hand to the Graveyard; add this card to your hand. \r\nYou can only activate 1 "Brilliant Spark" per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3111207,'Lappis Dragon',replace(replace('If this card is added from the Deck to your hand: You can reveal this card; Special Summon it. \r\nIf this card is added from your GY to your hand by a card effect: You can reveal this card; Special Summon this card, but banish it when it leaves the field. \r\nYou can only use 1 "Lappis Dragon" effect per turn, and only once that turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3113667,'Heavy Metal Raiders',replace(replace('The first time each DARK Machine monster you control would be destroyed by battle each turn, it is not destroyed, and if you took battle damage from the battle, it gains that much ATK after damage calculation, and keeps that ATK gain while this card is on the field. \r\nOnce per turn, if a monster you control that was originally a DARK Machine destroys a card(s) on the field by battle or card effect: You can Special Summon 1 DARK Machine monster from your hand.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3113836,'Gem-Knight Seraphinite',replace(replace('1 "Gem-Knight" monster + 1 LIGHT monster	\r\nMust first be Fusion Summoned with the above Fusion Materials. \r\nDuring your Main Phase, you can Normal Summon/Set 1 monster in addition to your Normal Summon/Set. \r\n(You can only gain this effect once per turn.)','\r',char(13)),'\n',char(10)),'Summoned by the effect of "Gem-Knight Seraphinite"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3117804,'Superheavy Samurai Big Benkei',replace(replace('When this card is Normal or Special Summoned: You can change its battle position. "Superheavy Samurai" monsters you control can attack while in face-up Defense Position. \r\nIf they do, apply their DEF for damage calculation.','\r',char(13)),'\n',char(10)),'Change battle position','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3121655,'Junk Dragonlet',replace(replace('If you control a Synchro Monster, you can Special Summon this card (from your hand). \r\nYou can only Special Summon "Junk Dragonlet" once per turn this way. \r\nWhen a Synchro Monster you control declares an attack: You can banish this card from your GY; that monster you control gains 800 ATK until the end of this turn. \r\nYou can only use this effect of "Junk Dragonlet" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129133,'Delta of Invitation',replace(replace('When this card is activated: You can send 1 Level 5 or higher Zombie monster from your Deck to the GY. \r\nYou can only use each of the following effects of "Delta of Invitation" once per turn. \r\nIf a Zombie monster is on the field: You can Special Summon 1 "Delta Token" (Zombie/DARK/Level 5/ATK 0/DEF 0). \r\nIf a monster(s) is added from the GY to the hand, while this card is in your GY (except during the Damage Step): You can add this card to your hand. \r\nYou can only activate 1 "Delta of Invitation" per turn.','\r',char(13)),'\n',char(10)),'Activate','Special Summon','Add to hand','Send the card to the GY?','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129134,'Delta Token','Special Summoned with the effect of "Delta of Invitation."','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129527,'Sleepy Scapegoats',replace(replace('Special Summon up to 4 "Scapegoat Tokens" (Beast/EARTH/Level 1/ATK 0/DEF 0) in Defense Position, then if your opponent controls a monster, you can Special Summon 1 "Swiftwind Panther Warrior" from your Deck, also for the rest of this turn, these Tokens cannot be Tributed for a Tribute Summon, also you cannot Special Summon from the Extra Deck, except Fusion Monsters. \r\nIf a card(s) you control that mentions "Dark Time Wizard" would be destroyed by battle or card effect, you can destroy 1 Token you control that was Special Summoned by this effect instead.','\r',char(13)),'\n',char(10)),'Activate','Select the number of Special Summons','Special Summon {CARD}?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129528,'Scapedgoat Tokens','Special Summoned by the effect of "Sleeping Scapegoats". If a card you control that mentions "Dark Time Wizard" in its card text would be destroyed by battle or card effect, you can destroy this card instead.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129529,'Scapedgoat Tokens',replace(replace('Special Summoned by the effect of "Sleeping Scapegoats". If a card you control that mentions "Dark Time Wizard" in its card text would be destroyed by battle or card effect, you can destroy this card instead.\r\n','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129530,'Scapedgoat Tokens',replace(replace('Special Summoned by the effect of "Sleeping Scapegoats". If a card you control that mentions "Dark Time Wizard" in its card text would be destroyed by battle or card effect, you can destroy this card instead.\r\n','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129531,'Scapedgoat Tokens',replace(replace('Special Summoned by the effect of "Sleeping Scapegoats". \r\nIf a card you control that mentions "Dark Time Wizard" in its card text would be destroyed by battle or card effect, you can destroy this card instead.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129635,'Tiki Curse',replace(replace('Special Summon this card as an Effect Monster (Rock/DARK/Level 4/ATK 1800/DEF 1000) (this card is also still a Trap). \r\nWhile this card is an Effect Monster, if another Trap Card that is a monster battles an opponent''s monster, after damage calculation: Destroy that opponent''s monster.','\r',char(13)),'\n',char(10)),'Destroy','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3134241,'Flying Kamakiri #2','A flying mantis that feeds primarily on insects.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3134857,'Orcustrion',replace(replace('2+ Effect Monsters, including an "Orcust" monster	\r\nThis linked card cannot be destroyed by battle or card effects. \r\nYou can target 3 of your banished Machine monsters; shuffle them into the Deck, and if you do, the ATK/DEF of any linked monster(s) your opponent currently controls become 0, also their effects are negated. \r\nYou can only use this effect of "Orcustrion" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3136426,'Level Limit - Area B','Change all face-up Level 4 or higher monsters to Defense Position.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3137279,'Ixeep, Omen of the Ghoti',replace(replace('If a Fish monster(s) is banished (except during the Damage Step): You can Special Summon this card from your hand. \r\nDuring the Standby Phase of the next turn after this card was banished: You can target 1 of your "Ghoti" Traps that is banished or in your GY; Set that target. \r\nYou can only use each effect of "Ixeep, Omen of the Ghoti" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3146695,'Psychic Reactor',replace(replace('If you control a Psychic-Type monster: Apply this effect to all Psychic-Type monsters you currently control, for the rest of this turn. \r\nWhen a Psychic-Type monster you control battles an opponent''s monster, after damage calculation: Banish that Psychic-Type monster, also banish that opponent''s monster.','\r',char(13)),'\n',char(10)),'Banish','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3149401,'Ultimate Dragon of Pride and Soul',replace(replace('3 monsters with 2500 original ATK/DEF	\r\nWhile you control this Fusion Summoned card, your opponent cannot target it with card effects, also it cannot be destroyed by your opponent''s card effects. \r\nWhile you have 25 or more cards in your GY, this Fusion Summoned card gains 4500 ATK/DEF. \r\nOnce per turn, if your opponent has 25 or more cards in their GY: You can destroy all cards your opponent controls.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3149764,'Tutan Mask','When a Spell/Trap Card is activated that targets exactly 1 Zombie monster on the field (and no other cards): Negate the activation, and if you do, destroy it.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3160805,'Exchange of Night and Day',replace(replace('You can only use 1 "Exchange of Night and Day" effect per turn, and only once that turn. \r\nYou can activate 1 of these effects;\r\n● Send 1 LIGHT Warrior monster from your hand to the GY, then add 1 DARK Warrior monster from your Deck to your hand, with the same Level the sent monster had in your hand.\r\n● Send 1 DARK Warrior monster from your hand to the GY, then add 1 LIGHT Warrior monster from your Deck to your hand, with the same Level the sent monster had in your hand.','\r',char(13)),'\n',char(10)),'Activate the effect','Use "Exchange of Night and Day"''s effect now?','Send a LIGHT monster to the GY, add a DARK monster to your hand','Send a DARK monster to the GY, add a LIGHT monster to your hand','','','','','','','','','','','','');
INSERT INTO texts VALUES(3167439,'Dark World Punishment',replace(replace('When a monster(s) would be Normal or Special Summoned: You can negate the Summon, and if you do, destroy that monster(s), then discard 1 Fiend monster. \r\nIf a "Dark World" monster(s) you control would be destroyed by battle or an opponent''s card effect, you can banish this card from your GY instead. \r\nYou can only use each effect of "Dark World Punishment" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3167573,'Puppet King',replace(replace('When your opponent adds a Monster Card(s) to their hand, except by drawing, you can Special Summon this card from your hand. \r\nIf you do, destroy it during your next turn''s End Phase.','\r',char(13)),'\n',char(10)),'Special Summon','Destroy','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3170832,'Takuhee','This bird is known far and wide as a harbinger of doom.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3171055,'Chain Dispel','When a Spell/Trap Card is activated: Destroy all cards in the controller''s Deck with the same name as the activated card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3204467,'Worm Solid',replace(replace('This card gains 100 DEF for each Reptile-Type "Worm" monster in your Graveyard. \r\nIf your opponent takes Battle Damage from attacking this card, at the end of the Damage Step select 1 Spell or Trap Card your opponent controls, and destroy it.','\r',char(13)),'\n',char(10)),'Destroy','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3211439,'Forbidden Apocrypha','Declare 1 monster card type (Fusion, Synchro, or Xyz); if 2 or more monsters of the declared type are on the field, make each player send all monsters of that type from their field to the GY.','Fusion','Synchro','Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3233859,'Psychic Wheeleder',replace(replace('If you control a Level 3 monster other than "Psychic Wheeleder", you can Special Summon this card (from your hand) in Defense Position. \r\nYou can only Special Summon "Psychic Wheeleder" once per turn this way. \r\nIf this card is sent to the GY as Synchro Material: You can target 1 monster on the field with less ATK than the Synchro Monster that used this card as material; destroy it. \r\nYou can only use this effect of "Psychic Wheeleder" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3244563,'Shield Spear','Target 1 face-up monster on the field; it gains 400 ATK/DEF until the end of this turn.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3248469,'Wannabee!',replace(replace('During the End Phase: You can send this card from your hand or field to the GY; excavate cards from the top of your Deck, equal to the number of your opponent''s unused Spell & Trap Zones, and you can Set 1 excavated Trap to your field (but send it to the GY during the next End Phase), also place the rest on the bottom of the Deck in any order. \r\nYou can only use this effect of "Wannabee!" once per turn.','\r',char(13)),'\n',char(10)),'','Set 1 Trap Card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3259760,'Spellbound','All face-up monsters your opponent currently controls cannot be Tributed, or used as material for a Fusion, Synchro, Xyz, or Link Summon, until the end of this turn.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3280747,'Sixth Sense',replace(replace('Declare 2 numbers from 1 to 6, then your opponent rolls a six-sided die, and if the result is one of the numbers you declared, you draw that many cards. \r\nOtherwise, send a number of cards from the top of your Deck to the Graveyard equal to the result.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3283679,'Evoltile Lagosucho',replace(replace('When this card is Normal Summoned: You can send 1 "Evolsaur" monster from your Deck to the Graveyard. \r\nWhen this card is flipped face-up: You can Special Summon 1 "Evoltile" monster from your Deck.','\r',char(13)),'\n',char(10)),'Send to the GY','Special Summon','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3285551,'Rite of Aramesir',replace(replace('If you control no "Adventurer Token": Special Summon 1 "Adventurer Token" (Fairy/EARTH/Level 4/ATK 2000/DEF 2000), then if you do not control "Fateful Adventure", you can place 1 "Fateful Adventure" from your Deck face-up in your Spell & Trap Zone. \r\nYou cannot activate the effects of monsters on the field the turn you activate this card, except Special Summoned monsters''. \r\nYou can only activate 1 "Rite of Aramesir" per turn.','\r',char(13)),'\n',char(10)),'Place "Fateful Adventure" from your Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3285552,'Adventurer Token','Special Summoned with the effect of "Rite of Aramesir."','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3287359,'Magical Musket Mastermind Caspar',replace(replace('2 monsters, including a LIGHT Fiend monster	\r\nDuring either player''s turn, you can activate "Magical Musket" Spell/Trap Cards from your hand. \r\nIf this card is Link Summoned: You can take 2 "Magical Musket" cards from your hand and/or Deck, including a monster, Special Summon 1 monster from it to your field, and Set the other to your opponent''s field. \r\nYou can only use this effect of "Magical Musket Mastermind Caspar" once per turn.','\r',char(13)),'\n',char(10)),'Activate','Activate by applying the effect of "Magical Musket Mastermind Caspar".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3289027,'Parl, Hermit of Dark World',replace(replace('If this card is discarded to the GY by card effect: You can target 1 "Dark World" monster in your GY, except "Parl, Hermit of Dark World"; Special Summon it to either field, then, if this card was discarded from your hand to your GY by an opponent''s card effect, you can Special Summon, to either field, 1 of your Fiend monsters that is banished, or in your hand or GY. \r\nYou can only use this effect of "Parl, Hermit of Dark World" once per turn.','\r',char(13)),'\n',char(10)),'','Special Summon 1 additional monster?','Special Summon to your field','Special Summon to your opponent''s field','','','','','','','','','','','','');
INSERT INTO texts VALUES(3292267,'Hieratic Sky Dragon Overlord of Heliopolis',replace(replace('2 Level 8 monsters	\r\nOnce per turn, when your opponent activates a card or effect that targets a card(s) on your field, your GY, and/or your banished card(s) (Quick Effect): You can detach 1 material from this card; negate the activation, and if you do, destroy that card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3294539,'Crimson Blade Dragon',replace(replace('1 "Resonator" Tuner + 1+ non-Tuners	\r\n(This card is always treated as "Crimson Blader".)	\r\nIf this card is Synchro Summoned: You can take 1 Level 8 or higher monster that cannot be Normal Summoned/Set from your Deck or GY, and either add it to your hand or Special Summon it, but negate its effects. \r\nYou can only use this effect of "Crimson Blade Dragon" once per turn. \r\nAt the start of the Damage Step, if this card battles a Level 5 or higher monster: You can destroy that monster.','\r',char(13)),'\n',char(10)),'Search effect','Destruction effect','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3298689,'The Phantom Knights'' Rank-Up-Magic Launch',replace(replace('During the Main Phase: Target 1 DARK Xyz Monster you control with no material; Special Summon from your Extra Deck, 1 DARK Xyz Monster that is 1 Rank higher than that monster you control, by using it as material, and if you do, attach this card to it as additional material. \r\n(This is treated as an Xyz Summon. Transfer its materials to the Summoned monster.) \r\nDuring your Main Phase: You can banish this card from your GY, then target 1 DARK Xyz Monster you control; attach 1 "The Phantom Knights" monster from your hand to that monster as material.','\r',char(13)),'\n',char(10)),'Special Summon','Xyz Material','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3300267,'Hieratic Dragon of Su',replace(replace('You can Special Summon this card (from your hand) by Tributing 1 "Hieratic" monster. \r\nOnce per turn: You can Tribute 1 other "Hieratic" monster from your hand or field, then target 1 Spell/Trap your opponent controls; destroy that target. \r\nIf this card is Tributed: Special Summon 1 Dragon Normal Monster from your hand, Deck, or GY, and make its ATK/DEF 0.','\r',char(13)),'\n',char(10)),'Destroy','Special Summon','Summoning method: Special Summon','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3322931,'Stellar Wind Wolfrayet',replace(replace('1 Tuner + 1+ non-Tuner monsters	\r\nYou can only control 1 "Stellar Wind Wolfrayet". \r\nGains 300 ATK each time another monster''s effect is activated, while the ATK of this card is less than 4000. \r\nOnce per turn, if this card''s ATK is 4000 or higher (Quick Effect): You can shuffle both this card and all monsters your opponent controls into the Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3355732,'Icejade Kosmochlor',replace(replace('If a face-up card is in a Field Zone, you can Special Summon this card (from your hand). \r\nYou can only Special Summon "Icejade Kosmochlor" once per turn this way. \r\nWhile "Icejade Cenote Enion Cradle" is on the field, monsters your opponent controls can only activate their effects the turn they are Summoned. \r\nIf your "Icejade" monster battles an opponent''s monster, that opponent''s monster loses 1000 ATK during that damage calculation only.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3356494,'Galaxy-Eyes Solflare Dragon',replace(replace('2 LIGHT monsters, including a monster with 2000 or more ATK	\r\nIf this card is Link Summoned: You can target 1 "Photon" or "Galaxy" monster in your GY; add it to your hand. \r\nDuring your opponent''s Main Phase (Quick Effect): You can discard 1 "Photon" card and 1 "Galaxy" card, OR discard 1 "Galaxy-Eyes Photon Dragon", then target 1 Special Summoned monster your opponent controls; destroy it. \r\nYou can only use each effect of "Galaxy-Eyes Solflare Dragon" once per turn.','\r',char(13)),'\n',char(10)),'','','Discard "Neo Galaxy-Eyes Photon Dragon"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3361010,'Kitsuni Kitsunebi',replace(replace('All face-up monsters on the field become FIRE. \r\nIf your opponent has a FIRE monster on their field or in their GY, while this card is in your GY: You can Special Summon this card. \r\nYou can only use this effect of "Kitsuni Kitsunebi" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3366982,'Alligator''s Sword Dragon',replace(replace('"Baby Dragon" + "Alligator''s Sword"	\r\nThis card can attack your opponent directly if the only face-up monsters they control are EARTH, WATER, or FIRE.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3370104,'Cyber Phoenix',replace(replace('While this card is in Attack Position, negate any Spell/Trap effects that target 1 Machine monster you control (and no other cards). \r\nWhen this card is destroyed by battle and sent to the GY: You can draw 1 card.','\r',char(13)),'\n',char(10)),'Draw','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3376703,'Arcana Force V - The Hierophant',replace(replace('You can discard this card; this turn, your opponent cannot activate cards or effects when an "Arcana Force" monster(s) is Summoned to your field. \r\nIf this card is Summoned: Toss a coin.\r\n● Heads: Special Summon 1 Level 4 or lower "Arcana Force" monster from your Deck with a different name from the monsters you control and in your GY.\r\n● Tails: Special Summon 1 "Arcana Force" monster from your Deck to your opponent''s field.','\r',char(13)),'\n',char(10)),'Your opponent cannot activate effects','Special Summon from the Deck','Face-up','Face-down','','','','','','','','','','','','');
INSERT INTO texts VALUES(3381441,'Gravekeeper''s Priestess',replace(replace('While there is no face-up Field Spell, the field is treated as "Necrovalley". \r\nAll "Gravekeeper''s" monsters on the field gain 200 ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3395226,'Mozarta the Melodious Maestra',replace(replace('Once per turn: You can Special Summon 1 LIGHT Fairy monster from your hand. \r\nYou cannot Special Summon other monsters the turn you activate this effect, except for LIGHT monsters.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3405259,'C-Crush Wyvern',replace(replace('Once per turn, you can either: Target 1 LIGHT Machine monster you control; equip this card to that target, OR: Unequip this card and Special Summon it. \r\nA monster equipped with this card is unaffected by your opponent''s Trap effects, also if the equipped monster would be destroyed by battle or card effect, destroy this card instead. \r\nIf this card is sent from the field to the GY: You can Special Summon 1 Union monster from your hand.','\r',char(13)),'\n',char(10)),'Equip','Special Summon','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3410461,'Alba-Lenatus the Abyss Dragon',replace(replace('"Fallen of Albaz" + 1+ Dragon monsters	\r\nCannot be used as Fusion Material. \r\nMust be either Fusion Summoned, or Special Summoned by sending the above cards from any Monster Zones to the GY. \r\nCan attack monsters a number of times each Battle Phase, up to the number of materials used for it. \r\nOnce per turn, during the End Phase, if this card is in the GY because it was sent there this turn: You can add 1 "Polymerization" Normal Spell or "Fusion" Normal Spell from your Deck to your hand.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3422200,'Crystron Sulfefnir',replace(replace('If this card is in your hand or GY: You can discard 1 "Crystron" card, except "Crystron Sulfefnir"; Special Summon this card in Defense Position, then destroy 1 card you control. \r\nIf this card on the field is destroyed by battle or card effect: You can Special Summon 1 "Crystron" monster from your Deck in Defense Position. \r\nYou can only use each effect of "Crystron Sulfefnir" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3428069,'Buster Blader, the Destruction Swordmaster',replace(replace('This card''s name becomes "Buster Blader" while on the field or in the GY. \r\nIf a monster(s) your opponent controls is destroyed by battle or card effect and sent to the GY: You can target 1 of those destroyed monsters; equip it to this card. \r\nOnce per turn: You can send 1 Monster Card you control that is equipped to this card to the GY; destroy all monsters your opponent controls with the same Type as that monster sent to the GY.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3429238,'Drill Warrior',replace(replace('"Drill Synchron" + 1+ non-Tuner monsters	\r\nOnce per turn, during your Main Phase 1: You can halve this card''s ATK, and if you do, it can attack your opponent directly this turn. \r\nOnce per turn: You can discard 1 card, and if you do, banish this card. \r\nDuring your next Standby Phase: Special Summon this card banished by this effect, then add 1 monster from your GY to your hand.','\r',char(13)),'\n',char(10)),'ATK becomes half','Banish this card','Special Summon','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3431737,'Assault Beast','You can discard this card to the GY; add 1 "Assault Mode Activate" from your Deck to your hand.','Add to hand','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3434362,'Rustin Mammoth',replace(replace('If this card is in your hand: You can banish Machine Link Monsters from your Extra Deck whose combined Link Ratings equal exactly 5; Special Summon this card. \r\nYou can target 1 card you control and 1 card your opponent controls; return them to the hand. \r\nThis is a Quick Effect if this card is linked to a Link-3 or higher Machine Link Monster. \r\nYou can only use each effect of "Rustin Mammoth" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','Return to the hand','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3441553,'Shimmering Shatterer of the Sacred Beasts',replace(replace('Activate 1 of these effects;\r\n● When your opponent activates a card or effect in response to your "Sacred Beast" monster''s effect activation: Negate that opponent''s effect.\r\n● Reveal 1 Level 10 "Sacred Beast" monster in your hand; discard 1 card, and if you do, add 1 "Illusion Gate" from your Deck to your hand.\r\n● Shuffle 3 "Sacred Beast" Traps from your GY and/or banishment into the Deck, then target 1 card your opponent controls; destroy it.	\r\nYou can only activate 1 "Shimmering Shatterer of the Sacred Beasts" per turn.','\r',char(13)),'\n',char(10)),'Activate','Negate the effect','Search effect','Destruction effect','','','','','','','','','','','','');
INSERT INTO texts VALUES(3461403,'The Immortal Bushi Mourns the Mortal Body',replace(replace('All monsters in your GY become Warrior monsters. \r\nOnce per turn, during the End Phase: You can destroy all monsters you control.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3486020,'Yoko, the Graceful Mayakashi',replace(replace('1 Tuner + 1+ non-Tuner monsters	\r\nYou can only control 1 "Yoko, the Graceful Mayakashi". \r\nYou can only use each of these effects of "Yoko, the Graceful Mayakashi" once per turn.\r\n● If a Synchro Monster in your possession whose original Level is 11 is destroyed by battle or an opponent''s card effect while this card is in the GY: You can banish 1 other Zombie monster from your GY, and if you do, Special Summon this card.\r\n● If this card is Special Summoned from the GY: You can destroy 1 monster your opponent controls.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3492538,'Insect Armor with Laser Cannon',replace(replace('Equip only to an Insect monster. \r\nIt gains 700 ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3493058,'Dicephoon',replace(replace('Roll a six-sided die and apply the result.\r\n● 2, 3, or 4: Destroy 1 Spell/Trap on the field.\r\n● 5: Destroy 2 Spells/Traps on the field.\r\n● 1 or 6: You take 1000 damage.','\r',char(13)),'\n',char(10)),'Roll a die','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3493978,'Don Turtle','When this card is Normal Summoned or Flip Summoned, you can Special Summon any number of "Don Turtle"(s) from your hand.','Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3496543,'Sinful Spoils of the White Forest',replace(replace('If you control a Fiend, Illusion, or Spellcaster monster: Activate 1 of these effects;\r\n● Special Summon 1 Fiend, Illusion, or Spellcaster monster from your hand.\r\n● Fusion Summon 1 Fusion Monster from your Extra Deck, using monsters from your hand or field.	\r\nIf this card is sent to the GY to activate a monster effect: You can Set this card.\r\nYou can only use each effect of "Sinful Spoils of the White Forest" once per turn.','\r',char(13)),'\n',char(10)),'Activate the effect','Set','Special Summon from the hand','Fusion Summon','','','','','','','','','','','','');
INSERT INTO texts VALUES(3507053,'Appliancer Dryer Drake',replace(replace('1 "Appliancer" monster	\r\nCannot be used as Link Material the turn it is Link Summoned. \r\nThis linked card gains 1000 ATK. \r\nOnce per turn, during your Battle Phase, if this card is co-linked (except during the Damage Step): You can switch the locations of 2 "Appliancer" monsters in your Main Monster Zones, including this card, and if you do, the other monster can make a second attack during each Battle Phase this turn. \r\nOnce per turn, when this card that is not co-linked is targeted for an attack: You can negate that attack.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3510565,'Stealth Bird',replace(replace('Once per turn: You can change this card to face-down Defense Position. \r\nWhen this card is Flip Summoned: Inflict 1000 damage to your opponent.','\r',char(13)),'\n',char(10)),'Change to face-down Defense Position','Inflict 1000 damage to your opponent','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3519195,'Evil Assault',replace(replace('Discard 1 card; take 1 Level 4 or lower "Evil HERO" monster from your Deck and either add it to your hand or Special Summon it, also for the rest of this turn after this card resolves, you cannot Special Summon from the Extra Deck, except "HERO" monsters. \r\nIf this card is in your GY, except the turn it was sent there: You can banish this card from your GY; add 1 "Dark Fusion" from your GY to your hand. \r\nYou can only use each effect of "Evil Assault" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','Recycle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3534077,'Coach Soldier Wolfbark',replace(replace('You can target 1 Level 4 FIRE Beast-Warrior monster in your GY; Special Summon it in Defense Position, but negate its effects. \r\nYou can only use this effect of "Coach Soldier Wolfbark" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3536537,'Evilswarm Zahak','If this face-up card you control is destroyed by your opponent''s card (by battle or card effect) and sent to your Graveyard: Target 1 Special Summoned Level 5 or higher monster on the field; destroy that target.','Destroy a monster','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3544583,'Allvain the Essence of Vanity','2 Normal Monsters','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3549275,'Dice Jar',replace(replace('FLIP: Both players roll a six-sided die. \r\nThe player with the lower result takes damage equal to their opponent''s roll x 500. \r\nHowever, if the winner rolled a 6, the loser takes 6000 damage. \r\nIf the rolls are the same, both players roll again.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3557275,'White Duston','The proudust of them all.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3560069,'Latency',replace(replace('If this card is added from your GY to your hand by a card effect: You can Special Summon it from your hand. \r\nIf this card Summoned this way is sent to the GY as Link Material: You can draw 1 card. \r\nYou can only use each effect of "Latency" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3567660,'Link Back',replace(replace('Target 1 Link Monster you control in the Extra Monster Zone; move that monster you control to your Main Monster Zone it points to, then, you can send cards from the top of your Deck to the GY equal to its Link Rating. \r\nYou can only activate 1 "Link Back" per turn.','\r',char(13)),'\n',char(10)),'Move to another zone','Select a card to move','Send a card from your Deck to the GY?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3573512,'Swordsman of Landstar','An amateur with a sword, this fairy warrior relies on its mysterious powers.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3574681,'Golden Rule',replace(replace('(This card is always treated as a "Crystal" card.)	\r\nPlace 2 "Crystal Beast" monsters from your Deck face-up in your Spell & Trap Zone as Continuous Spells, then Special Summon 1 "Crystal Beast" monster from your hand or GY with a different name than those cards, and if you do, equip it with this card. \r\nWhen this card leaves the field, destroy that monster. \r\nYou can only activate 1 "Golden Rule" per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3576031,'Crystolic Potential',replace(replace('All "Crystron" monsters you control gain 300 ATK/DEF. \r\nOnce per turn, during the End Phase: You can draw cards equal to the number of "Crystron" Synchro Monsters you Synchro Summoned this turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3580032,'Merlin',replace(replace('You can only use each effect of "Merlin" once per turn.\r\n● You can Tribute this card; Special Summon 1 "Noble Knight" monster from your Deck.	\r\nYou cannot Special Summon monsters the turn you activate this effect, except "Noble Knight" monsters.\r\n● (Quick Effect): You can banish this card from your GY; immediately after this effect resolves, Synchro Summon 1 "Noble Knight" Synchro Monster using monsters you control.\r\n● (Quick Effect): You can banish this card from your GY; immediately after this effect resolves, Xyz Summon 1 "Noble Knight" Xyz Monster using monsters you control.','\r',char(13)),'\n',char(10)),'Synchro Summon 1 "Noble Knight" Synchro Monster','Xyz Summon 1 "Noble Knight" Xyz Monster','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3594985,'Majespecter Draco - Ryu',replace(replace('Pendulum Scale = 5\r\n[ Pendulum Effect ]\r\nIf you have a "Majespecter" or "Dracoslayer" card in your other Pendulum Zone: You can add 1 "Majespecter" card from your Deck to your hand, then you can destroy 1 card in your Pendulum Zone. \r\nYou can only use this effect of "Majespecter Draco - Ryu" once per turn.\r\n----------------------------------------\r\n[ Monster Effect ]\r\n2 Level 4 monsters	\r\nIf you can Pendulum Summon Level 4, you can Pendulum Summon this face-up card from your Extra Deck. \r\nIf a monster(s) is Tributed while this card is on the field (except during the Damage Step): You can detach 1 material from this card; Special Summon 1 Level 6 or lower WIND Spellcaster monster from your Deck. \r\nYou can only use this effect of "Majespecter Draco - Ryu" up to twice per turn. \r\nIf this card in the Monster Zone is destroyed by battle or card effect, or Tributed: You can place this card in your Pendulum Zone.','\r',char(13)),'\n',char(10)),'Search the Deck','Special Summon from the Deck','Place in the Pendulum Zone','Destroy 1 card in your Pendulum Zone?','','','','','','','','','','','','');
INSERT INTO texts VALUES(3598351,'Evil HERO Toxic Bubble',replace(replace('You can Special Summon this card (from your hand), but you cannot Special Summon for the rest of this turn, except "HERO" monsters. \r\nYou can only Special Summon "Evil HERO Toxic Bubble" once per turn this way. \r\nIf this card is Special Summoned, and you control a Fusion Monster that must be Special Summoned with "Dark Fusion": You can draw 2 cards. \r\nYou can only use this effect of "Evil HERO Toxic Bubble" once per turn.','\r',char(13)),'\n',char(10)),'','Draw','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3603242,'Shreddder','Once per turn: You can send 1 Machine-Type monster from your hand to the Graveyard, then target 1 monster your opponent controls with a Level less than or equal to the sent monster''s; destroy that target.','Destroy','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606209,'One Who Hunts Souls','This dangerous creature brandishes a soul-sucking sword.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606728,'Gagaga Girl',replace(replace('You can target 1 "Gagaga Magician" you control; this card''s Level becomes the current Level of that monster. \r\nAn Xyz Monster that was Summoned using only this card and other "Gagaga" monsters as material gains this effect.\r\n● When it is Xyz Summoned: You can target 1 Special Summoned monster your opponent controls; its ATK becomes 0.','\r',char(13)),'\n',char(10)),'Change Level','ATK becomes 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606729,'Gagaga Girl',replace(replace('You can target 1 "Gagaga Magician" you control; this card''s Level becomes the current Level of that monster. \r\nAn Xyz Monster that was Summoned using only this card and other "Gagaga" monsters as material gains this effect.\r\n● When it is Xyz Summoned: You can target 1 Special Summoned monster your opponent controls; its ATK becomes 0.','\r',char(13)),'\n',char(10)),'Change Level','ATK becomes 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3611830,'Endymion, the Mighty Master of Magic',replace(replace('Pendulum Scale = 8\r\n[ Pendulum Effect ]\r\nYou can remove 6 Spell Counters from your field; Special Summon this card from the Pendulum Zone, then count the number of cards you control that can have a Spell Counter, destroy up to that many cards on the field, and if you do, place Spell Counters on this card equal to the number of cards destroyed. \r\nYou can only use this effect of "Endymion, the Mighty Master of Magic" once per turn.\r\n----------------------------------------\r\n[ Monster Effect ]\r\nOnce per turn, when a Spell/Trap Card or effect is activated (Quick Effect): You can return 1 card you control with a Spell Counter to the hand, and if you do, negate the activation, and if you do that, destroy it. \r\nThen, you can place the same number of Spell Counters on this card that the returned card had. \r\nWhile this card has a Spell Counter, your opponent cannot target it with card effects, also it cannot be destroyed by your opponent''s card effects. \r\nWhen this card with a Spell Counter is destroyed by battle: You can add 1 Normal Spell from your Deck to your hand.','\r',char(13)),'\n',char(10)),'','','Place a Spell Counter?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3627449,'Skull Guardian','You can Ritual Summon this card with "Novox''s Prayer".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3629090,'Cyber Angel Idaten',replace(replace('You can Ritual Summon this card with "Machine Angel Ritual". \r\nIf this card is Ritual Summoned: You can add 1 Ritual Spell from your Deck or GY to your hand. \r\nIf this card is Tributed: You can make all Ritual Monsters you control gain 1000 ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3642509,'Elemental HERO Great Tornado',replace(replace('1 "Elemental HERO" monster + 1 WIND monster	\r\nMust be Fusion Summoned and cannot be Special Summoned by other ways. \r\nIf this card is Fusion Summoned: Halve the ATK and DEF of all face-up monsters your opponent currently controls.','\r',char(13)),'\n',char(10)),'Change ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3643300,'The Legendary Fisherman','While "Umi" is on the field, this card is unaffected by Spell effects and cannot be targeted for attacks, but does not prevent your opponent from attacking you directly.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3648368,'Ally of Justice Searcher',replace(replace('Once per turn: You can discard 1 card, then target 1 face-down Defense Position monster your opponent controls; change that target to face-up Attack Position. \r\n(Flip monsters'' effects are not activated.)','\r',char(13)),'\n',char(10)),'Change battle position','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3657444,'Cyber Valley',replace(replace('You can activate 1 of these effects.\r\n● When this card is targeted for an attack: You can banish this card; draw 1 card, then end the Battle Phase.\r\n● You can target 1 face-up monster you control and this card; banish both those targets, then draw 2 cards.\r\n● You can target 1 card in your GY; banish both this card and 1 card from your hand, then place that target on top of the Deck.','\r',char(13)),'\n',char(10)),'Banish this card, draw 1 card, and end the Battle Phase','Banish other monsters and this card, draw 2 cards','Banish cards from your hand and this card, then recycle cards in the GY','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3659803,'Overload Fusion','Fusion Summon 1 DARK Machine Fusion Monster from your Extra Deck, by banishing materials mentioned on it from your field or GY.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3679218,'Knightmare Mermaid',replace(replace('1 "Knightmare" monster, except "Knightmare Mermaid"	\r\nIf this card is Link Summoned: You can discard 1 card; Special Summon 1 "Knightmare" monster from your Deck, then, if this card was co-linked when this effect was activated, you can draw 1 card. \r\nYou can only use this effect of "Knightmare Mermaid" once per turn. \r\nMonsters on the field lose 1000 ATK/DEF, unless they are co-linked.','\r',char(13)),'\n',char(10)),'','Draw a card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3682106,'Double Snare','Target 1 face-up card on the field that has an effect that negates Trap effects; destroy it.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3685372,'CXyz Gimmick Puppet Fanatix Machinix',replace(replace('3 Level 9 monsters	\r\nIf this card is Special Summoned: You can add 1 "Puppet" Trap from your Deck to your hand. \r\nYou can detach 1 material from this card; Special Summon 1 monster from either GY to your opponent''s field in Defense Position. \r\nIf a monster(s) is Special Summoned to your opponent''s field (except during the Damage Step): You can target 1 of them; destroy it, and if you do, inflict damage to your opponent equal to half its original ATK. \r\nYou can only use each effect of "CXyz Gimmick Puppet Fanatix Machinix" once per turn.','\r',char(13)),'\n',char(10)),'Add to hand','Special Summon a monster from either GY to your opponent''s field','Inflict damage','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3693034,'Karakuri Cash Inn',replace(replace('Target 1 "Karakuri" monster you control and 1 Effect Monster your opponent controls; change the battle position of your monster, and if you do, negate the effects of that opponent''s monster until the end of this turn. \r\nIf you control a "Karakuri" monster(s): You can banish this card from your GY, then target 1 face-up monster on the field; change that monster''s battle position. \r\nYou can only activate 1 "Karakuri Cash Inn" per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3701074,'Dark Cure','When your opponent Summons a monster(s), they gain Life Points equal to half the ATK of 1 of the Summoned monsters of your choice.','Gain LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3715284,'Meklord Army Deployer Obbligato',replace(replace('During your Main Phase: You can activate this effect; destroy this card, and if you do, Special Summon 2 "Meklord Army" monsters from your Deck in Defense Position, except "Meklord Army Deployer Obbligato", also you cannot Special Summon monsters for the rest of this turn, except Machine monsters. \r\nIf this card is sent to the GY: You can activate this effect; during the End Phase of this turn, you can inflict 100 damage to your opponent for each "Meklord" monster you control. \r\nYou can only use each effect of "Meklord Army Deployer Obbligato" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3717252,'Shaddoll Beast',replace(replace('FLIP: You can draw 2 cards, then discard 1 card.\r\nIf this card is sent to the GY by a card effect: You can draw 1 card. \r\nYou can only use 1 "Shaddoll Beast" effect per turn, and only once that turn.','\r',char(13)),'\n',char(10)),'Draw 2 card(s)','Draw 1 card(s)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3723262,'Wizard @Ignister',replace(replace('If you control a Cyberse monster that was Special Summoned from the Extra Deck: You can target 1 DARK Cyberse monster in your GY; Special Summon both this card in your hand and that monster, in Defense Position, also you cannot Special Summon for the rest of this turn, except Cyberse monsters. \r\nYou can banish this card from your field or GY, then target 1 monster your opponent controls; change its battle position. \r\nYou can only use each effect of "Wizard @Ignister" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','Change battle position','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3732747,'Water Element','A sea-dwelling spirit that takes away sight by clouding the area in fog.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3734202,'Naturia Sacred Tree',replace(replace('If this card is sent to the GY: Add 1 "Naturia" card from your Deck to your hand, except "Naturia Sacred Tree". \r\nYou can only use 1 of the following effects of "Naturia Sacred Tree" per turn, and only once that turn.\r\n● You can Tribute 1 EARTH Insect monster; Special Summon 1 Level 4 or lower EARTH Plant monster from your Deck.\r\n● You can Tribute 1 EARTH Plant monster; Special Summon 1 Level 4 or lower EARTH Insect monster from your Deck.','\r',char(13)),'\n',char(10)),'Special Summon an EARTH Plant monster','Special Summon an EARTH Insect monster','Search the Deck','Use the effect?','','','','','','','','','','','','');
INSERT INTO texts VALUES(3739500,'Ruler of the End of the World',replace(replace('You can Ritual Summon this card with a "End of the World" card. \r\nThis card''s name becomes "Demise, King of Armageddon" while in the hand or on the field. \r\nYou can only use each of the following effects of "Ruler of the End of the World" once per turn. \r\nYou can reveal this card in your hand, pay 2000 LP, then banish 1 Ritual Spell from your Deck; apply that card''s activation effect that Ritual Summons a monster. \r\nYou can pay 2000 LP; destroy all other cards on the field, then this card gains 2900 ATK.','\r',char(13)),'\n',char(10)),'Copy Ritual','Destruction effect','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3743515,'Steamed Sabersaurus',replace(replace('2 Level 4 monsters	\r\nYou can detach 1 material from this card; destroy 1 Dinosaur monster in your hand or face-up field, then you can change the battle position of 1 monster on the field. \r\nAt the start of the Damage Step, if your other Dinosaur monster battles: You can destroy this card, and if you do, that Dinosaur monster gains 2000 ATK until the end of the Battle Phase. \r\nYou can only use each effect of "Steamed Sabersaurus" once per turn.','\r',char(13)),'\n',char(10)),'Destroy','Destroy and increase ATK','Change battle position?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3752422,'Performapal Lebellman',replace(replace('Pendulum Scale = 1\r\n[ Pendulum Effect ]\r\nOnce per turn: You can increase the Levels of all Pendulum Summoned monsters you currently control by 1 (even if this card leaves the field).\r\n----------------------------------------\r\n[ Monster Effect ]\r\nOnce per turn: You can declare a Level from 1 to 5, then target 1 other "Performapal" monster you control; until the end of this turn, reduce this card''s Level by the declared Level, and if you do, increase the Level of the other monster by the same amount.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3758046,'D/D/D Wave King Caesar',replace(replace('2 Level 4 Fiend monsters	\r\n(Quick Effect): You can detach 1 material from this card; at the end of the Battle Phase this turn, Special Summon from your GY as many monsters destroyed this turn as possible, but during the Standby Phase of the next turn, take 1000 damage for each monster Special Summoned by this effect. \r\nIf this card is sent from the field to the GY: You can add 1 "Dark Contract" card from your Deck to your hand. \r\nYou can only use each effect of "D/D/D Wave King Caesar" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon the monster destroyed this turn at the end of the Battle Phase','Search the Deck','Take damage','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3773196,'D.D. Scout Plane',replace(replace('During the End Phase, if this card is currently banished, and was banished this turn: Special Summon it in face-up Attack Position. \r\nThis effect can only activate once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3775068,'Indiora Doom Volt the Cubic Emperor',replace(replace('Cannot be Normal Summoned/Set. \r\nMust be Special Summoned (from your hand) by sending 3 "Cubic" monsters you control to the Graveyard, and cannot be Special Summoned by other ways. \r\nIf Summoned this way, this card gains 2400 ATK. \r\nIf this card is Special Summoned from the hand: Inflict 800 damage to your opponent. \r\nIf this card in your possession is sent to your Graveyard by your opponent''s card (by battle or card effect): You can target up to 3 "Cubic" monsters in your Graveyard; Special Summon them, then you can add 1 "Cubic" card from your Deck or Graveyard to your hand.','\r',char(13)),'\n',char(10)),'Effect damage','Special Summon a monster from the GY','Add 1 "Cubic" card to your hand?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3779493,'Night''s End Administrator',replace(replace('"Night''s End Sorcerer" + 1+ non-Tuner monsters	\r\nIf this card is Special Summoned, or if another Spellcaster monster(s) is Special Summoned to your field: You can target 1 card in your opponent''s GY; banish it. \r\nIf this card is destroyed by battle, or if this card in its owner''s Monster Zone is destroyed by an opponent''s card effect: You can target 1 Level 4 or lower Spellcaster monster in your GY; Special Summon it. \r\nYou can only use this effect of "Night''s End Administrator" once per turn.','\r',char(13)),'\n',char(10)),'Banish cards from your opponent''s GY','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3779662,'Gladiator Beast Andabata',replace(replace('"Gladiator Beast Augustus" + 2 "Gladiator Beast" monsters	\r\nMust first be Special Summoned (from your Extra Deck) by shuffling the above cards you control into the Deck. \r\nIf Summoned this way: You can Special Summon 1 Level 7 or lower "Gladiator Beast" Fusion Monster from your Extra Deck, ignoring its Summoning conditions. \r\nAt the end of the Battle Phase, if this card battled: You can return it to the Extra Deck; Special Summon 2 "Gladiator Beast" monsters from your Deck.','\r',char(13)),'\n',char(10)),'','Special Summon','Select "Gladiator Beast"','Select a "Gladiator Beast" monster','','','','','','','','','','','','');
INSERT INTO texts VALUES(3784434,'Rampaging Rhynos',replace(replace('Once per turn, this card can move to an adjacent (horizontal) unoccupied Monster Card Zone. \r\nIf this card attacks the monster in its same column, this card gains 500 ATK during the Damage Step.','\r',char(13)),'\n',char(10)),'Move to another zone','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3790062,'Number 65: Djinn Buster',replace(replace('2 Level 2 DARK monsters	\r\nWhen your opponent activates a monster effect (Quick Effect): You can detach 2 materials from this card; negate the activation, and if you do, inflict 500 damage to your opponent.','\r',char(13)),'\n',char(10)),'Negate the activation and inflict damage','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3792766,'Trickstar Delfiendium',replace(replace('2+ "Trickstar" monsters	\r\nWhen this card declares an attack while pointing to a "Trickstar" monster: You can target your banished "Trickstar" cards, up to the number of Link Monsters your opponent controls; add them to your hand, and if you do, this card gains 1000 ATK for each card added, until the end of this turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3797883,'Slot Machine','The machine''s ability is said to vary according to its slot results.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3806388,'Core of Chaos',replace(replace('Cannot be Normal Summoned/Set. \r\nMust be Special Summoned by card effect. \r\nIf this face-up card would leave the field, banish it instead. \r\nYou can only use each of the following effects of "Core of Chaos" once per turn. \r\nYou can banish 1 DARK monster from your hand or GY; Special Summon this card from your hand, also you cannot Special Summon monsters from the Extra Deck for the rest of this turn, except LIGHT or DARK Synchro Monsters. \r\nIf this card is Special Summoned: You can target 1 of your banished "Shell of Chaos"; Special Summon it.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3810071,'Monk Fighter','Battle Damage to this card''s controller from a battle involving this card becomes 0.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3814632,'Skypalace Gangaridai',replace(replace('2 Level 10 monsters	\r\nYou can detach 1 material from this card, then target 1 card your opponent controls; destroy that target, and if you do, inflict 1000 damage to your opponent. \r\nYou can only use the effect of "Skypalace Gangaridai" once per turn. \r\nCannot attack the turn you activate this effect.','\r',char(13)),'\n',char(10)),'Destroy and inflict damage','','','','','','','','','','','','','','','');
