INSERT INTO texts VALUES(5043013,'Firewall Dragon',replace(replace('2+ monsters	\r\nOnce while face-up on the field (Quick Effect): You can target monsters on the field and/or GY up to the number of monsters co-linked to this card; return them to the hand. \r\nIf a monster this card points to is destroyed by battle or sent to the GY: You can Special Summon 1 Cyberse monster from your hand. \r\nYou can only use each effect of "Firewall Dragon" once per turn.','\r',char(13)),'\n',char(10)),'Return to its owner''s hand','Special Summon','Effect already activated','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5050644,'Aroma Garden',replace(replace('Once per turn, if you control an "Aroma" monster: You can gain 500 LP, also all monsters you control gain 500 ATK/DEF until the end of your opponent''s next turn (even if this card leaves the field). \r\nIf a face-up "Aroma" monster you control is destroyed by battle or card effect and sent to the GY: Gain 1000 LP.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
