INSERT INTO texts VALUES(23338098,'Assault Blackwing - Chidori the Rain Sprinkling',replace(replace('1 Tuner + 1 or more non-Tuner monsters	\r\nIf this card is Synchro Summoned using a "Blackwing" monster as Material, it is treated as a Tuner monster while face-up on the field. \r\nThis card gains 300 ATK for each "Blackwing" monster in your Graveyard. \r\nWhen this card is destroyed and sent to the Graveyard: You can target 1 Winged Beast-Type Synchro Monster in your Graveyard, except "Assault Blackwing - Chidori the Rain Sprinkling"; Special Summon it.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23361526,'Hi-Speedroid Cork Shooter',replace(replace('1 Tuner + 1+ non-Tuner monsters	\r\nIf this card is Synchro Summoned: You can activate 1 of these effects;\r\n● Add 1 "Speedroid" Spell/Trap from your Deck to your hand.\r\n● If all materials that were used for the Synchro Summon of this card were "Speedroid" monsters, and are all in your GY, Special Summon all of them.	\r\nYou cannot Special Summon the turn you activate this effect, except WIND monsters. \r\nYou can only use this effect of "Hi-Speedroid Cork Shooter" once per turn.','\r',char(13)),'\n',char(10)),'Activate the chosen effect','Search the Deck','Special Summon materials','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23377425,'S-Force Bridgehead',replace(replace('When this card is activated: You can add 1 "S-Force" monster from your Deck to your hand. \r\nWhen an opponent''s monster declares an attack on your "S-Force" monster in its same column: You can activate this effect; that monster you control cannot be destroyed by that battle. \r\nYou can only use this effect of "S-Force Bridgehead" once per turn. \r\nYou can only activate 1 "S-Force Bridgehead" per turn.','\r',char(13)),'\n',char(10)),'Add 1 "S-Force" monster from your Deck to your hand?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23377694,'Performapal Sellshell Crab',replace(replace('Pendulum Scale = 2\r\n[ Pendulum Effect ]\r\nOnce per turn, when a "Performapal" monster you control is destroyed by battle: You can target 1 "Performapal" or "Odd-Eyes" card in your Pendulum Zone; Special Summon it.\r\n----------------------------------------\r\n[ Monster Effect ]\r\nOnce per turn: You can target 1 Pendulum Monster you control; it gains 300 ATK for each "Performapal" monster you currently control, until the end of this turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23379054,'Ghost Charon, the Underworld Boatman',replace(replace('If your opponent controls a monster, and you control no other monsters: You can target 1 Fusion Monster in your Graveyard; banish both this card from the field and that target, and if you do, Special Summon 1 Dragon-Type Synchro Monster from your Extra Deck whose Level equals the total Levels those 2 monsters had (original Level, if face-down). \r\nYou can only use this effect of "Ghost Charon, the Underworld Boatman" once per turn. \r\nYou cannot Special Summon monsters the turn you activate this effect, except Dragon-Type monsters.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23384666,'Gizmek Taniguku, the Immobile Intellect',replace(replace('If this card is Normal or Special Summoned: You can take 1 Machine monster whose ATK equals its own DEF from your Deck and place it on top of your Deck. \r\nYou can banish this card from your GY, then target 1 Machine monster in your GY whose ATK equals its own DEF; Special Summon it in Defense Position. \r\nYou can only use each effect of "Gizmek Taniguku, the Immobile Intellect" once per turn.','\r',char(13)),'\n',char(10)),'','','Select the card to place on top of the Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23401839,'Senju of the Thousand Hands','When this card is Normal or Flip Summoned: You can add 1 Ritual Monster from your Deck to your hand.','Add 1 Ritual Monster to your hand','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23401840,'Senju of the Thousand Hands','When this card is Normal or Flip Summoned: You can add 1 Ritual Monster from your Deck to your hand.','Add 1 Ritual Monster to your hand','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23408872,'Tradetoad',replace(replace('Once per turn, you can Tribute 1 Aqua-Type monster to select 1 "Frog" monster in your Graveyard, except "Frog the Jam". \r\nSpecial Summon that monster from your Graveyard.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
