INSERT INTO texts VALUES(24221808,'Overmind Archfiend',replace(replace('1 Psychic Tuner + 2+ non-Tuner Psychic monsters	\r\nOnce per turn: You can target 1 Psychic monster in your GY; banish it. \r\nWhen this card is sent from the field to the GY: Special Summon as many monsters as possible that were banished by this effect.','\r',char(13)),'\n',char(10)),'Banish','Special Summon','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24224830,'Called by the Grave','Target 1 monster in your opponent''s GY; banish it, and if you do, until the end of the next turn, its effects are negated, as well as the activated effects and effects on the field of monsters with the same original name.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24224831,'Called by the Grave','Target 1 monster in your opponent''s GY; banish it, and if you do, until the end of the next turn, its effects are negated, as well as the activated effects and effects on the field of monsters with the same original name.','','','','','','','','','','','','','','','','');
