INSERT INTO texts VALUES(31305911,'Marshmallon',replace(replace('Cannot be destroyed by battle. \r\nAfter damage calculation, if this card was attacked, and was face-down at the start of the Damage Step: The attacking player takes 1000 damage.','\r',char(13)),'\n',char(10)),'Take 1000 damage','','','','','','','','','','','','','','','');
