INSERT INTO texts VALUES(31444249,'Void Imagination',replace(replace('"Infernoid" monsters you control whose original Levels are 2 or higher become Level 1 and all battle damage they inflict to your opponent is halved. \r\nYou can send this card to the GY; Fusion Summon 1 "Infernoid" Fusion Monster from your Extra Deck, using monsters from your hand or field as material. \r\nIf your opponent controls a monster that was Special Summoned from the Extra Deck, and you do not, you can also use up to 6 monsters in your Deck as Fusion Materials.','\r',char(13)),'\n',char(10)),'Also select Fusion Materials from the Deck?','Also select Fusion Materials from your hand/field?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31444250,'Void Imagination',replace(replace('"Infernoid" monsters you control whose original Levels are 2 or higher become Level 1 and all battle damage they inflict to your opponent is halved. \r\nYou can send this card to the GY; Fusion Summon 1 "Infernoid" Fusion Monster from your Extra Deck, using monsters from your hand or field as material. \r\nIf your opponent controls a monster that was Special Summoned from the Extra Deck, and you do not, you can also use up to 6 monsters in your Deck as Fusion Materials.','\r',char(13)),'\n',char(10)),'Also select Fusion Materials from the Deck?','Also select Fusion Materials from your hand/field?','','','','','','','','','','','','','','');
