INSERT INTO texts VALUES(31991800,'Majespecter Raccoon - Bunbuku',replace(replace('Pendulum Scale = 5\r\n----------------------------------------\r\n[ Monster Effect ]\r\nWhen this card is Normal or Special Summoned: You can add 1 "Majespecter" monster from your Deck to your hand. \r\nYou can only use this effect of "Majespecter Raccoon - Bunbuku" once per turn. \r\nWhile this card is in your Monster Zone, your opponent cannot target it with card effects, also it cannot be destroyed by your opponent''s card effects.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32003338,'Number 34: Terror-Byte',replace(replace('3 Level 3 monsters	\r\nOnce per turn: You can detach 1 Xyz Material from this card to target 1 Level 4 or lower Attack Position monster your opponent controls; gain control of it until the End Phase.','\r',char(13)),'\n',char(10)),'Take control','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32003339,'Number 34: Terror-Byte',replace(replace('3 Level 3 monsters	\r\nOnce per turn: You can detach 1 Xyz Material from this card to target 1 Level 4 or lower Attack Position monster your opponent controls; gain control of it until the End Phase.','\r',char(13)),'\n',char(10)),'Take control','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32012841,'Millennium Shield','A famous shield said to belong to an ancient Egyptian Pharaoh. Legends tell of its power to block any strong attack.','','','','','','','','','','','','','','','','');
