INSERT INTO texts VALUES(37742478,'Honest',replace(replace('During your Main Phase: You can return this face-up card from the field to the hand. \r\nDuring the Damage Step, when a LIGHT monster you control battles (Quick Effect): You can send this card from your hand to the GY; that monster gains ATK equal to the ATK of the opponent''s monster it is battling, until the end of this turn.','\r',char(13)),'\n',char(10)),'Return to hand','Increase ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37742479,'Honest',replace(replace('During your Main Phase: You can return this face-up card from the field to the hand. \r\nDuring the Damage Step, when a LIGHT monster you control battles (Quick Effect): You can send this card from your hand to the GY; that monster gains ATK equal to the ATK of the opponent''s monster it is battling, until the end of this turn.','\r',char(13)),'\n',char(10)),'Return to hand','Increase ATK','','','','','','','','','','','','','','');
