INSERT INTO texts VALUES(41234315,'Fake Explosion',replace(replace('Activate only when an opponent''s monster declares an attack. \r\nMonsters cannot be destroyed by this battle. \r\nAfter damage calculation, Special Summon 1 "Summon Reactor ・SK" from your hand or Graveyard.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
