INSERT INTO texts VALUES(41255165,'Penguin Ninja',replace(replace('FLIP: You can target up to 2 Spells/Traps your opponent controls; return them to the hand.\r\nYou can target 1 "Penguin" monster you control; change it to face-down Defense Position. \r\nYou can only use this effect of "Penguin Ninja" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
