INSERT INTO texts VALUES(41424250,'Chaos End Ruler - Ruler of the Beginning and the End',replace(replace('Cannot be Normal Summoned/Set. \r\nMust be Special Summoned (from your hand) by banishing 1 LIGHT Warrior and 1 DARK Fiend monster from your GY. \r\nThis card''s Special Summon cannot be negated. \r\nNeither player can activate cards or effects when this card is Special Summoned. \r\nIf you control this card that was Summoned its own way: You can pay 1000 LP; banish as many cards from your opponent''s field and GY as possible, then inflict 500 damage to your opponent for each card banished by this effect. \r\nYou can only use this effect of "Chaos End Ruler - Ruler of the Beginning and the End" once per turn.','\r',char(13)),'\n',char(10)),'','Banish','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41426869,'Black Illusion Ritual',replace(replace('This card is used to Ritual Summon "Relinquished". \r\nYou must also Tribute a monster from your hand or field whose Level is 1 or more.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41431329,'Vylon Cube','If this card is sent to the Graveyard for the Synchro Summon of a LIGHT monster: You can add 1 Equip Spell Card from your Deck to your hand.','Add to hand','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41436536,'Elemental HERO Phoenix Enforcer',replace(replace('"Elemental HERO Avian" + "Elemental HERO Burstinatrix"	\r\nMust be Fusion Summoned and cannot be Special Summoned by other ways. \r\nThis card cannot be destroyed by battle.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41440148,'Performapal Hip Hippo',replace(replace('After you Normal Summon this card, you can Tribute Summon 1 Level 7 or higher monster in face-up Attack Position during your Main Phase this turn, in addition to your Normal Summon/Set. \r\n(You can only gain this effect once per turn.)','\r',char(13)),'\n',char(10)),'Summoned by the effect of "Performapal Hip Hippo"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41440817,'Jelly Cannon','When a monster declares an attack: Target 1 monster on the field; shuffle it into the Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41442341,'Puppet Master','When this card is Tribute Summoned: You can pay 2000 LP, then target 2 Fiend monsters in your GY; Special Summon those targets, but they cannot attack this turn.','Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41443249,'Rescue-ACE Preventer',replace(replace('You can banish 1 "Rescue-ACE" card from your GY; Special Summon this card from your hand. \r\nIf you control another "Rescue-ACE" monster (Quick Effect): You can target 1 Effect Monster your opponent controls; change it to face-down Defense Position. \r\nIf this card is sent to the GY: You can target 1 of your banished "Rescue-ACE" monsters, except a Level 8 monster; Special Summon it. \r\nYou can only use each effect of "Rescue-ACE Preventer" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41456841,'Metamorphosed Insect Queen',replace(replace('Cannot be Normal Summoned/Set. \r\nMust be Special Summoned by a card effect. \r\nIf another Insect monster is on the field, your opponent cannot target Insect monsters you control with card effects, also they cannot be destroyed by your opponent''s card effects. \r\nAt the end of the Damage Step, if this card attacked: You can Tribute 1 monster; this card can attack an opponent''s monster again in a row. \r\nOnce per turn, during the End Phase: You can Special Summon 1 "Insect Monster Token" (Insect/EARTH/Level 1/ATK 100/DEF 100).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
