INSERT INTO texts VALUES(41458361,'Adamancipator Luminous',replace(replace('2 Effect Monsters, including a Synchro Monster	\r\nIf this card is Link Summoned, or a monster(s) is Special Summoned to a zone(s) this card points to: You can target 1 monster in your field or GY that has a Level; Special Summon 1 "Glimmer Token" (Rock/LIGHT/ATK 0/DEF 0) with the same Level. \r\nWhen another monster on the field activates its effect (Quick Effect): You can place it on top of the Deck. \r\nYou can only use each effect of "Adamancipator Luminous" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','Return to the Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41458362,'Glimmer Token','Special Summoned by the effect of "Adamancipator Luminous".','','','','','','','','','','','','','','','','');
