INSERT INTO texts VALUES(54020393,'Enneacraft Release',replace(replace('Place 1 "Enneacraft" Pendulum Monster from your Deck in your Pendulum Zone. \r\nIf this card is in your GY, except the turn it was sent there: You can banish it; add 1 face-up "Enneacraft" monster from your Extra Deck to your hand. \r\nYou can only activate 1 "Enneacraft Release" per turn.','\r',char(13)),'\n',char(10)),'Place','Recycle','','','','','','','','','','','','','','');
