INSERT INTO texts VALUES(54100561,'FaSolfachord Fancia',replace(replace('Pendulum Scale = 5\r\n[ Pendulum Effect ]\r\nPendulum Summons of your "Solfachord" Pendulum Monsters cannot be negated.\r\n----------------------------------------\r\n[ Monster Effect ]\r\nWhile you have an odd Pendulum Scale in your Pendulum Zone, if your "Solfachord" Pendulum Monster would be destroyed by battle, you can destroy this card instead. \r\nDuring your Main Phase: You can add 1 "Solfachord" Pendulum Monster from your Deck to your Extra Deck face-up, except "FaSolfachord Fancia". \r\nYou can only use this effect of "FaSolfachord Fancia" once per turn.','\r',char(13)),'\n',char(10)),'','Select a card to add to the Extra Deck','','','','','','','','','','','','','','');
