INSERT INTO texts VALUES(54631665,'SPYRAL Resort',replace(replace('Your opponent cannot target other "SPYRAL" cards you control with card effects. \r\nOnce per turn: You can add 1 "SPYRAL" monster from your Deck to your hand. \r\nOnce per turn, during your End Phase, shuffle 1 monster from your GY into the Deck or destroy this card.','\r',char(13)),'\n',char(10)),'Search the Deck','Shuffle 1 monster from your GY into the Deck','Destroy this card','','','','','','','','','','','','','');
