INSERT INTO texts VALUES(54635100,'Linkerbell',replace(replace('2 monsters	\r\nYou cannot Link Summon this card unless you have at least 3 more cards in your Extra Deck than your opponent''s.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54635862,'Gentlemander',replace(replace('When an opponent''s monster declares an attack: You can Special Summon this card from your hand. \r\nYour opponent''s monsters cannot attack any monsters, except this one.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54641720,'Destiny HERO - Dreadnought Master',replace(replace('2 Level 5 or higher "Destiny HERO" monsters	\r\nMust be either Fusion Summoned, or Special Summoned (from your Extra Deck) by Tributing 1 "Destiny HERO - Dreadmaster". \r\nYou can only Special Summon "Destiny HERO - Dreadnought Master" once per turn this way, no matter which method you use. \r\nIf this card is Special Summoned: You can add 2 "Destiny HERO" monsters and/or cards that mention a "Destiny HERO" monster''s card name from your Deck to your hand. \r\nThis card''s ATK becomes the total original ATK of all other "Destiny HERO" monsters in your field and GY.','\r',char(13)),'\n',char(10)),'Add to hand','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54652250,'Man-Eater Bug','FLIP: Target 1 monster on the field; destroy it.','','','','','','','','','','','','','','','','');
