INSERT INTO texts VALUES(54656950,'Anchorbolt Hedgehog',replace(replace('If you control "Junk Warrior" or a monster that mentions it, except "Anchorbolt Hedgehog", and this card is in your GY (Quick Effect): You can Special Summon this card in Defense Position, also you cannot Special Summon from the Extra Deck for the rest of this turn, except Synchro Monsters. \r\nYou can only use this effect of "Anchorbolt Hedgehog" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon','','','','','','','','','','','','','','','');
