INSERT INTO texts VALUES(54757758,'Mudragon of the Swamp',replace(replace('2 monsters with the same Attribute but different Types	\r\nYour opponent cannot target this card, or monsters on the field with the same Attribute as this card, with card effects. \r\nOnce per turn (Quick Effect): You can declare 1 Attribute; this card becomes that Attribute until the end of this turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54762426,'Treasure Map',replace(replace('You can only activate this card in response to the activation of an effect that would return this card from the field to the hand. \r\nDraw 2 cards from your Deck and discard 1 card from your hand.','\r',char(13)),'\n',char(10)),'Draw','','','','','','','','','','','','','','','');
