INSERT INTO texts VALUES(60764609,'Fiendsmith Engraver',replace(replace('You can discard this card; add 1 "Fiendsmith" Spell/Trap from your Deck to your hand. \r\nYou can target 1 "Fiendsmith" Equip Card you control and 1 monster on the field; send them to the GY. \r\nIf this card is in your GY: You can shuffle 1 other LIGHT Fiend monster from your GY into the Deck/Extra Deck; Special Summon this card. \r\nYou can only use each effect of "Fiendsmith Engraver" once per turn.','\r',char(13)),'\n',char(10)),'Search effect','Send to the GY','Special Summon','','','','','','','','','','','','','');
