INSERT INTO texts VALUES(76471944,'Superheavy Samurai Ninja Sarutobi',replace(replace('1 Machine-Type Tuner + 1 or more non-Tuner "Superheavy Samurai" monsters	\r\nThis card can attack while in face-up Defense Position. \r\nIf it does, apply its DEF for damage calculation. \r\nOnce per turn, during either player''s turn, if you have no Spell/Trap Cards in your Graveyard: You can target 1 Spell/Trap Card on the field; destroy it, and if you do, inflict 500 damage to your opponent.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76473843,'Majesty''s Pegasus',replace(replace('"Majespecter" monsters on the field gain 300 ATK/DEF. \r\nYou can Tribute 1 WIND Spellcaster monster; Special Summon 1 Level 4 or lower "Majespecter" monster from your Deck. \r\nYou can only use this effect of "Majesty''s Pegasus" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76500786,'Star Power!!',replace(replace('During damage calculation, if your Link Monster battles an opponent''s monster: Your monster gains ATK equal to the total Levels/Ranks of the monsters it points to x 400, during that damage calculation only. \r\nYou can only activate 1 "Star Power!!" per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76504386,'Number 39: Utopia the Envoy of Light',replace(replace('2 Level 4 monsters	\r\nCannot be destroyed by battle, except with a "Number" monster. \r\n(Quick Effect): You can detach 1 material from this card, then target 1 monster you control; the first time it would be destroyed by battle or card effect this turn, it is not destroyed. \r\nWhen the second attack of this turn is declared: You can make this card gain 2500 ATK, and if you do, it gains this effect.\r\n● When this card destroys a monster by battle and sends it to the GY: You can Special Summon it to your field.','\r',char(13)),'\n',char(10)),'Destruction protection','Increase ATK','Special Summon','Effect already activated','','','','','','','','','','','','');
