INSERT INTO texts VALUES(76520646,'Infinity Dark',replace(replace('This card is treated as a Normal Monster while face-up on the field or in the Graveyard. \r\nWhile this card is face-up on the field, you can Normal Summon it to have it be treated as an Effect Monster with this effect:\r\n● When this card declares an attack, you can change the battle position of 1 face-up monster your opponent controls.','\r',char(13)),'\n',char(10)),'Change battle position','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76524506,'Garden Rose Flora',replace(replace('1 Tuner + 1+ non-Tuner monsters	\r\nYou can target 1 card in the Field Zone; destroy it, then Special Summon to its controller''s field, 1 "Rose Token" (Plant/DARK/Level 2/ATK 800/DEF 800) in Attack Position, also you cannot Special Summon from the Extra Deck for the rest of this turn, except Synchro Monsters. \r\nYou can only use this effect of "Garden Rose Flora" once per turn. \r\nOnce per Chain, during your opponent''s Main Phase, you can (Quick Effect): Immediately after this effect resolves, Synchro Summon using this card you control.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
