INSERT INTO texts VALUES(97612389,'Monster Tamer','A master of monsters that exercises control over several creatures.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97616504,'Sky Striker Mecharmory - Hercules Base',replace(replace('Activate this card only if you control no monsters in your Main Monster Zone. \r\nThe equipped monster cannot attack directly. \r\nIt can make a second attack on monsters during each Battle Phase. \r\nIf the equipped monster destroys a monster by its attack while you have 3 or more Spells in your GY: Draw 1 card. \r\nIf this card is sent from the field to the GY by a card effect: You can target up to 3 "Sky Striker" cards in your GY, except "Sky Striker Mecharmory - Hercules Base"; shuffle them into the Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97617181,'Galaxy Zero',replace(replace('Target 1 "Photon" or "Galaxy" monster in your GY; Special Summon it in Attack Position and equip it with this card. \r\nIt cannot attack or activate its effects. \r\nIf it would be destroyed by battle or card effect during the Battle Phase, you can destroy this card instead. \r\nIf this face-up card leaves the field: The equipped monster''s ATK becomes 0. \r\nYou can only activate 1 "Galaxy Zero" per turn.','\r',char(13)),'\n',char(10)),'ATK becomes 0','Use "Galaxy Zero"''s effect instead of being destroyed?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97623219,'Element Valkyrie',replace(replace('This monster gets the following effect(s) while there is a monster(s) with the following Attribute(s) on the field:\r\n● FIRE: This card gains 500 ATK.\r\n● WATER: Control of this card cannot switch.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97631303,'Magicians'' Souls',replace(replace('You can send up to 2 Spells/Traps from your hand and/or field to the GY; draw that many cards. \r\nIf this card is in your hand: You can send 1 Level 6 or higher Spellcaster monster from your Deck to the GY, then activate 1 of these effects;\r\n● Special Summon this card.\r\n● Send this card to the GY, then, you can Special Summon 1 "Dark Magician" or 1 "Dark Magician Girl" from your GY.	\r\nYou can only use each effect of "Magicians'' Souls" once per turn.','\r',char(13)),'\n',char(10)),'Special Summon this card','Send this card to the GY','Special Summon from the GY?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97637162,'Handigallop',replace(replace('Cannot attack directly. \r\nGains ATK equal to the difference between your LP and your opponent''s. \r\nIf your LP are higher than your opponent''s, you take any battle damage your opponent would have taken from battles involving this attacking card, instead.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97639441,'Photon Jumper',replace(replace('When an opponent''s monster declares an attack: You can activate this effect; skip your next Battle Phase, also Special Summon this card from your hand, then end this Battle Phase. \r\nIf this card is sent to the GY: You can add 1 "Photon" or "Galaxy" Spell/Trap from your Deck to your hand. \r\nYou can only use each effect of "Photon Jumper" once per turn.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97642679,'Dark Master - Zorc',replace(replace('You can Ritual Summon this card with "Contract with the Dark Master". \r\nOnce per turn: You can roll a six-sided die, then destroy all monsters your opponent controls if you roll 1 or 2, destroy 1 monster your opponent controls if you roll 3, 4 or 5, or destroy all monsters you control if you roll 6.','\r',char(13)),'\n',char(10)),'Roll a die','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97648103,'World Legacy''s Heart',replace(replace('Target 2 "World Chalice" monsters in your GY with different names; add them to your hand. \r\nIf your linked Link Monster would be destroyed by battle, you can banish this card from your GY instead. \r\nYou can only activate 1 "World Legacy''s Heart" per turn.','\r',char(13)),'\n',char(10)),'Use "World Legacy''s Heart"''s effect instead of being destroyed?','','','','','','','','','','','','','','','');
